programs.sol:
"""A boundary pulse and a negative response to particular GH spellings.

Bare gh/igh/ough fragments are strongest; weigh, sigh, rough and their
inflections also respond. Frequent completed words such as through are not
assigned that fragment response. A split grammatical ending inherits part of
its GH-bearing stem's response. Smaller branches cover GitHub, ghayn, some
other h-bearing fragments, and positive principle/element vocabulary.
These are spelling/lexical rules, not a general rule about a word's meaning.
"""
READS = ()

GH_FRAGMENTS = {
    'gh': -3.2, 'igh': -4.5, 'ugh': -3.7,
    'ough': -3.1, 'agh': -3.0, 'ogh': -2.7,
    'leigh': -2.7, 'orough': -1.4, 'burgh': -1.3,
}
GH_STEMS = {
    'weigh': -3.3, 'sigh': -2.3, 'neigh': -2.3,
    'rough': -2.1, 'cough': -1.6, 'tough': -0.9,
    'trough': -1.15, 'thorough': -0.7,
}
SUFFIXES = {'s', 'es', 'ed', 'ing', 'ly', 'ness'}


def spelling_response(token):
    word = token.strip().lower()
    if token == '<|endoftext|>':
        return 1.84
    if word in GH_FRAGMENTS:
        value = GH_FRAGMENTS[word]
        if word in {'gh', 'igh', 'ough', 'agh', 'ogh'}:
            if token.strip().isupper():
                value *= 0.65
            elif token.strip()[0].isupper():
                value *= 0.7
            elif token.startswith(' '):
                value *= 0.8
        return value
    if word in GH_STEMS:
        return GH_STEMS[word] * (0.4 if token.strip().isupper() else 1.0)
    for stem in ('weigh', 'sigh'):
        if word in {stem + 'ed', stem + 'ing', stem + 's'}:
            return 0.8 * GH_STEMS[stem]
    if word == 'roughly':
        return -1.15
    if word in {'tougher', 'toughness', 'toughest'}:
        return -0.7
    if word == 'thoroughly':
        return -0.25
    if word.startswith('ghan'):
        return -1.15 if token.startswith(' ') else -1.65
    if word in {'hugh', 'hughes', 'pittsburgh'}:
        return -1.0
    if word in {'ghi', 'ghz'}:
        return -0.65
    if word == 'غ':  # Arabic ghayn, conventionally romanized as gh.
        return -0.95
    if 'github' in word:
        return -1.1 if word.startswith(('.', '"')) else -0.7
    if word == 'ithub':
        return -0.55
    if word in {'principle', 'principles'}:
        return 0.77
    if word in {'element', 'elements'}:
        value = 0.34 if word.endswith('s') else 0.56
        return value if token.startswith(' ') else 0.5 * value
    if word == 'high':
        return -0.2
    if word.lstrip('-_') in {'weight', 'weights', 'weighted', 'weighting'}:
        return -0.27
    if word in {'ight', 'ights', 'ought', 'ught'}:
        return -0.35
    if word in {'ighth', 'ght'}:
        return -0.9
    if word in {'rh', 'wh'}:
        return -0.75 if word == 'rh' else -0.3
    if word in {'ograph', 'ography', 'ographs', 'raph'}:
        return -0.4
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else 0.0
    value = spelling_response(token)
    # A split grammatical ending still belongs to the GH-bearing word.
    if token.lower() in SUFFIXES:
        value += 0.44 * previous
    gh_stem = 'gh' in token.lower() and value < -0.6
    return (doc, value if gh_stem else 0.0), value

programs.haiku:
"""Layer-0 MLP down-projection component 1536.

What it does, in plain terms:
- Fires strongly positive (about +1.8) on the end-of-text token <|endoftext|>,
  which marks a document boundary.
- Fires strongly negative on the letters "gh" when they are spelled but silent or
  part of an -ough / -igh ending: the bare pieces "gh", "ough", "igh", "ugh",
  and whole words like "weigh", "weighed", "weighs", "rough", "cough", "sigh".
  The pieces are the big negative values; "github" is mildly negative.
  Common words that contain "gh" (through, light, right, high, thought) are ~0.
- Weakly positive (about +0.6) on a few academic nouns: element, principle, ...

The program reads only the newest token of the prefix; it has no state.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"

# "gh" spelled as a fragment or ending: the letters themselves, with no word around them.
GH_PIECES = {"gh", "ough", "igh", "ugh", "ogh", "agh", "eigh", "orough"}

# Whole words where "gh" is silent or sounds like f.
GH_WEIGH = {"weigh", "weighed", "weighing", "weighs", "leigh"}

# Whole words with -ough / -igh endings, weaker.
GH_ROUGH = {"rough", "roughly", "cough", "tough", "thorough", "trough", "sigh"}

GITHUB = {"github", ".github", '"github', "ithub"}

ACADEMIC_NOUNS = {"element", "elements", "principle", "principles", "materials", "concept",
                  "expression", "structure"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == END_OF_TEXT:
        return carry, 1.84
    word = token.strip().lower()
    if word in GH_PIECES:
        value = -3.0
    elif word in GH_WEIGH:
        value = -3.0
    elif word in GH_ROUGH:
        value = -2.0
    elif word in GITHUB:
        value = -1.0
    elif word in ACADEMIC_NOUNS:
        value = 0.6
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Recognize the document end marker and the recurring word “principle.”"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    if token == "<|endoftext|>":
        return None, 1.82
    if "principle" in token:
        return None, 0.7
    return None, 0.0

programs.sol:
"""A lexical life/birth/coming-into-being signal, centered on 生.

生 (life, birth, raw, student) is strongest alone; its compounds are weaker.
Related English words cover living, generation, occurrence, and development.
Split compounds such as 発 + 生 have a reduced response, too.
A few inflected translations and short expressions are included. This is not
a general topic classifier: unrelated words in a life story still predict zero.
"""

READS = ()

# The sets describe meaning families, including common inflections.
FAMILIES = (
    (2.3, 'arise arises arisen arising arose'),
    (1.4, '''produce produces produced producing production producer producers
             productions produ emerge emerges emerged emerging emergence'''),
    (1.2, '''life lives lifetime lifelong lifecycle living lived alive wildlife
             livelihood reproduce reproduced reproduction reprodu reproductive'''),
    (1.0, '''student students graduate graduates graduation survive survives
             survived surviving survival occur occurs occurring occurred occurrence'''),
    (0.85, '''live nature natural naturally native appear appears appeared appearing
              happen happens happened happening grow grows grew growing growth
              rise rises risen rising biology biological ecosystem ecology'''),
    (0.75, '''create creates created creating creation develop develops developed
              developing development formed forming formation evolve evolved evolution
              introduce introduces introduced introducing introduction gener'''),
    (0.55, '''come comes came coming exist exists existed existence grown
              arrive arrived arriving pregnancy spring early died lifestyle'''),
    (0.35, 'form forms origin origins give gives gave giving gen initial'),
)
LEXICON = {w: a for a, words in FAMILIES for w in words.split()}


def lexical(raw):
    text = raw.strip()
    if text == '生':
        return 6.6 if raw.startswith(' ') else 8.25
    if text == '생':
        return 7.6 if raw.startswith(' ') else 5.0
    if '生' in text:
        # Whole-life, renewed-life and ecological compounds are particularly strong.
        if text == '一生':
            return 7.3
        if text in {'人生', '新生', '生生'}:
            return 5.3
        if text in {'再生', '重生', '民生'} or '人生' in text:
            return 4.0
        if text in {'生态', '生態'}:
            return 3.4
        if text in {'发生', '發生', '产生', '產生', '生成', '研究生', '生まれ'}:
            return 3.2
        if any(w in text for w in ('医生', '醫生', '维生素', '維生素')):
            return 0.2
        if '卫生' in text or '衛生' in text:
            return 0.5
        if '学生' in text or '學生' in text:
            return 1.6
        if '生命' in text:
            return 1.2
        return 2.4 * (2 / len(text)) ** 0.5
    if text == '발생':
        return 4.0
    if text == '생성':
        return 2.4
    if text in {'학생', '생산', '생활', '생명'}:
        return 1.8
    if text in {'产', '誕', '诞'} or text.startswith(('起こ', '起き')):
        return 2.0
    if '辈子' in text:
        return 2.5
    if text in {'産', '產', '自然', '天然', '形成', '出现', '出現', '成长', '成長'}:
        return 1.2
    if text in {'起', '成', '立', '发', '發', '增', '春', '活', '创造', '創造',
                '增长', '上涨', '发展', '發展', '成立', '出来', '来了'}:
        return 0.85
    if text in {'来', '來', '存在'}:
        return 0.6

    word = text.lower().lstrip('_-./(')
    if word == 'birth':
        return 2.05
    if word == 'born':
        return 1.0 if raw == 'born' else 1.85
    if word == 'births':
        return 1.65
    if word.startswith(('generat', 'regenerat')) or 'ogenesis' in word:
        if word.startswith('generator'):
            return 0.8
        return 1.3 if word.startswith('generation') else 1.6
    if word in {'bio', 'biol'}:
        return 1.4
    if word.startswith(('жизн', 'жив', 'leben', 'viv')):
        return 1.0
    if word.startswith('производ'):
        return 1.2
    if word == 'sinh':  # Vietnamese: birth / life
        return 2.7
    return LEXICON.get(word, 0.0)


# The positive signal extends to these complete expressions, not every next token.
OF_NOUNS = frozenset('''
life lifetime survival creation formation production generation generations
growth development existence evolution introduction
'''.split())
GROW = frozenset('grow grows growing grew grown'.split())
COME = frozenset('come comes coming came'.split())
# Occurrence, sanitation, birth, derivation, teacher/student, parasitism.
SPLIT_COMPOUNDS = frozenset({
    '発生', '衛生', '誕生', '派生', '出生', '先生', '学生', '學生', '寄生',
})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = lexical(raw)
    # Recognize compounds even when the tokenizer splits before 生.
    if raw == '生' and previous[-1:] + '生' in SPLIT_COMPOUNDS:
        value = 4.8
    elif word == 'of':
        if previous in {'birth', 'emergence'}:
            value = 1.1
        elif previous in OF_NOUNS:
            value = 0.55
    elif word == 'up':
        value = 1.05 if previous in GROW else 0.15
        if previous in COME:
            value = 0.6
    elif word == 'out':
        value = 0.55 if previous in COME else 0.1
    return (doc, word), float(value)

programs.luna:
"""Approximate rare title-header and human-group noun activations."""
READS = ()

# Nouns naming people or collectives, rather than an unrestricted word-ID table.
PERSON_OR_GROUP = frozenset({
    "artist", "journalist", "patient", "poet", "society", "worker",
    "职工", "患者", "车主", "演员", "艺人", "投资者", "社区", "群体",
})
SOCIAL_MODIFIERS = frozenset({
    "American", "British", "female", "male", "younger", "女", "男",
    "青年", "年轻", "英国",
})


def step(carry, prefix, upstream):
    """Flag a document Title header or a people/group noun after a social descriptor."""
    if len(prefix.token_ids) >= 2:
        current = prefix.token_strings[-1].strip()
        previous = prefix.token_strings[-2].strip()
        if current == "Title" and prefix.token_strings[-2] == "<|endoftext|>":
            return None, -0.7163
        if current in PERSON_OR_GROUP and previous in SOCIAL_MODIFIERS:
            return None, -0.85
    return None, 0.0

programs.haiku:
"""Word detector for "answer / respond / return" (layer-0 MLP feature, layers.0.mlp.down_proj:1541).

The component's activation depends almost only on the current token (within a token it varies
little). It is large on the word "answer" in any language, medium on "respond / reply /
response", smaller on "return / output", and small on "solution / solve / question / address".
Every other token gives about 0. The program looks up the current token, lowercased and
stripped of its leading space, in these word families and returns the family's typical value.
"""

READS = ()

ANSWER = {
    "answer", "answers", "answering", "answered", "answerer",
    "回答", "答案", "问答", "ответ", "réponse", "respuesta", "antwort", "답",
}
RESPOND = {
    "respond", "responds", "responded", "responding", "respondent", "respondents", "responder",
    "response", "responses", "reply", "replies", "replied", "replying",
    "resp", "res", "ponse", "ponses", "回复", "回应", "应",
}
RETURN = {
    "return", "returns", "returned", "returning", "output", "outputs", "ans", "回", "返回", "输出",
}
SOLVE_ASK = {
    "solution", "solutions", "solve", "solved", "solver", "resolve", "resolved", "resolution",
    "question", "questions", "address", "addressed", "addresses", "解决", "解", "问题",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in ANSWER:
        value = 5.7
    elif word in RESPOND:
        value = 1.5
    elif word in RETURN:
        value = 1.0
    elif word in SOLVE_ASK:
        value = 0.65
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate the component's mean token-rarity and spelling-shape trend.

Log vocabulary index is a coarse rarity proxy: later entries have larger
mean activations on training text. ASCII title-case pieces, mixed-case
identifiers, and incomplete Unicode pieces get extra weight. Length,
grammatical endings, and writing system adjust the estimate. Numbers and
whitespace stay near zero; angle-bracketed markers have separate values.
State only tracks document changes for a small first-token correction.
This omits the component's finer, individual-token preferences.
"""
import math
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    index = int(prefix.token_ids[-1])
    document = prefix.document_ids[-1]
    start = carry is None or carry != document
    if text.startswith('<') and text.endswith('>'):
        return document, {
            '<tool_call>': 1.32, '<tool_response>': -0.50,
            '<|im_start|>': 0.27, '<|im_end|>': -0.10,
        }.get(text, 0.0)
    if not text:
        return document, -0.004
    if text.isdecimal():
        return document, 0.0

    rarity = max(0.0, math.log(max(index, 1) / 8000))
    curvature = -0.006 * rarity * rarity
    if '\ufffd' in text:
        # A bare incomplete piece gets a larger estimate than one joined
        # to visible text or to several replacement characters.
        value = 0.65 + 0.13 * rarity
        if token.startswith(' '):
            value -= 0.18
        if len(text) > 1:
            value -= 0.66
        if any(c.isalpha() for c in text):
            value += 0.14
        if text.count('\ufffd') > 1:
            value += 0.11
        if index < 256:  # Single raw-byte tokens, rather than merged pieces.
            value = 0.23
        return document, value
    if not any(c.isalpha() for c in text):
        value = 0.066 * rarity + curvature
        if '✓' in text or '✔' in text:
            value += 0.55
        elif '✝' in text or '†' in text:
            value += 0.62
        elif len(text) > 1 and set(text) == {'^'}:
            value += 0.67
        return document, value

    if text.isascii():
        word = text.lstrip('./_-')
        length = min(len(word), 12)
        value = -0.007 + (0.065 + 0.01 * min(length, 5)) * rarity
        value += curvature + 0.01 * max(0, length - 5)
        if word != text:
            value += 0.016
        if token.startswith(' '):
            value += 0.023 + 0.018 * rarity
        if word.istitle():
            value += 0.10 * rarity
        elif word.isupper():
            value -= 0.013
        elif not word.islower():
            value += 0.57 - 0.056 * rarity
        if len(word) > 4:
            if word.endswith('ness'):
                value += 0.15
            elif word.endswith(('ly', 'al')):
                value -= 0.14
            elif word.endswith(('ed', 'ive', 'tion')):
                value -= 0.09
            elif word.endswith(('ing', 's')):
                value -= 0.07
    else:
        value = 0.029 + 0.134 * rarity + curvature
        value -= 0.007 * min(len(text), 5)
        names = ' '.join(unicodedata.name(c, '') for c in text)
        for script, offset, slope in (
            ('CJK', -0.22, 0.062), ('CYRILLIC', -0.073, -0.016),
            ('ARABIC', -0.166, 0.024), ('GREEK', -0.20, 0.0),
            ('HIRAGANA', -0.023, 0.022), ('KATAKANA', -0.062, 0.0),
            ('HANGUL', -0.143, 0.049),
        ):
            if script in names:
                value += offset + slope * rarity
    if start:
        value -= 0.08
    return document, float(value)

"""Mostly a Japanese/Korean oblique-case and adverbial-marker detector.

The Japanese particle に and Korean 에 give the largest response. Other
case/linking particles are weaker; subject/topic markers are slightly negative.
Fused Japanese に phrases get reduced responses, estimated from their length.
Some fixed adverbs and attributive (rather than adverbial) forms are weaker.
Whitespace-bearing Korean 에/로/게 forms are downweighted. Chinese 而/而是
get a small positive response; unmatched tokens get zero. This approximation
uses only the current token, not a grammatical parse or preceding context.
"""

READS = ()

# Japanese case/linking particles and connective endings.
JAPANESE = {
    'に': 12.1, 'にも': 9.7, 'には': 6.0, 'へ': 5.1, 'への': 3.2,
    'で': 3.7, 'から': 2.4, 'まで': 1.7, 'と': 1.9, 'を': 1.1,
    'として': 3.8, 'して': 1.6, 'でも': 1.3, 'では': 1.0,
    'ので': 1.2, 'な': 0.8, 'く': 0.9, 'は': -0.4, 'の': -0.1,
    'が': -0.2, 'て': 0.9, 'れて': 2.3, 'えて': 1.9,
    'させて': 2.8, 'せて': 2.3, 'されて': 1.6, 'けて': 1.3,
    'めて': 1.2, 'という': 0.7, 'とは': 1.0, 'とも': 1.7,
    '」と': 2.6, 'としても': 2.7, 'としては': 2.6,
    'にして': 6.5, 'に対して': 5.2, 'にて': 3.4,
}
# Korean locative, directional, instrumental, dative and adverbial endings.
KOREAN = {
    '에': 8.4, '로': 4.7, '으로': 5.1, '에게': 5.7,
    '에는': 4.7, '에도': 4.8, '에서': 1.6, '기에': 4.5,
    '히': 4.1, '하게': 4.2, '게': 2.5, '적으로': 3.4, '대로': 3.5,
    '을': 0.7, '를': 0.7, '와': 0.7, '하고': 0.7,
    '이': -0.4, '가': -0.4, '은': -0.4, '의': -0.3,
    '엔': 2.6, '들에게': 4.6,
}
FIXED_ADVERBS = {
    '特に', '非常に', '本当に', '確かに', '基本的に', 'まさに',
    '気軽に', 'どのように',
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.strip()
    if s in JAPANESE:
        value = JAPANESE[s]
    elif s in KOREAN:
        value = KOREAN[s]
        if raw != s and s in ('에', '로', '게'):
            value *= 0.25 if s == '게' else 0.5
    elif s in FIXED_ADVERBS:
        value = 1.5
    elif s in ('ことに', 'さんに', 'それに', '日に', '年に'):
        value = 9.0
    elif s in ('さらに', 'すでに', 'ちなみに'):
        value = 2.7
    elif s.endswith('には'):
        value = 3.0
    elif s.endswith('に'):
        if s in ('的に', '常に', 'ずに'):
            value = 4.4
        else:
            value = 6.8 if len(s) == 2 else 4.3
    elif s.startswith('に'):
        if s in ('による', 'における', 'に関する') or s.startswith('にく'):
            value = 0.3
        elif s.startswith('に向'):
            value = 3.4
        elif len(s) == 2:
            value = 7.0
        elif s.startswith(('について', 'において', 'に関して')):
            value = 2.0 if len(s) < 6 else 1.0
        else:
            value = 3.1 if len(s) < 5 else 1.5
    elif 'を' in s:
        value = 1.4
    elif s.endswith('で'):
        value = 2.0
    elif s in ('しく', 'よく', '良く', '大きく', 'うまく', 'なく', 'やすく'):
        value = 2.7
    elif s in ('而', '而是'):
        value = 1.2
    else:
        value = 0.0
    return None, float(value)

programs.luna:
"""Recognize strong Japanese に and a small set of related particles.

Attached forms of に get a weaker response. Other Japanese case/connective
particles, Korean postpositions and Chinese 而 get a modest positive response.
"""

READS = ()

JAPANESE_PARTICLES = {
    "で", "と", "を", "して", "への", "ために", "ように",
    "から", "とも", "ものを",
}
KOREAN_PARTICLES = {"으로", "에는", "로", "를"}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()

    if token == "に":
        return None, 11.6
    if token.startswith("に"):
        return None, 6.0
    if "に" in token:
        return None, 4.0
    if token in JAPANESE_PARTICLES or token in KOREAN_PARTICLES:
        return None, 2.5
    if token == "而" or token.startswith("而是"):
        return None, 1.3
    return None, 0.0

programs.sol:
"""Detect printing vocabulary and text-output commands from token spellings.

The largest negative response is on `print` and Chinese 印 (print/seal).
Other print-shaped words and output commands receive smaller responses.
Console logging is distinguished from other uses of `.log`. A print word's
split endings, or an immediately following `of`/`the`, retain a response.
Unrecognized tokens receive zero; these rules do not decide whether code runs.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._/(#-')
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    if '\ufffd' in token and previous:
        # Decode only broken-byte tokens to recognize a completed Chinese word.
        tail = prefix.text_prefixes[-1][-2:]
        if tail.endswith('印'):
            word = '印'
        elif tail in {'打印', '印刷', '指纹', '足迹'}:
            word = tail
    lower = word.lower()
    before = previous.strip().lstrip('._/(#-').lower()
    strength = 0.0

    if word == '印':
        strength = 8.3
    elif word in {'打印', '印刷'}:
        strength = 5.1
    elif lower in {'print', 'prints', 'printing'}:
        strength = 5.8
        if word == 'Print':
            strength = 6.5
        elif word == 'Printing':
            strength = 4.8
    elif lower == 'printed':
        strength = 4.4
    elif lower == 'println':
        strength = 3.7
    elif lower in {'printf', 'fprintf', 'sprintf'}:
        strength = 1.1
        if word == 'Printf' and token.startswith('.'):
            strength = 1.9
        elif lower == 'sprintf':
            strength = 0.5
    elif lower == 'printstacktrace':
        strength = 1.8
