    'questo': -0.70, 'questa': -0.67, 'deze': -0.89, 'acest': -1.06,
    'tersebut': -1.23, 'này': -0.66, 'هذه': -0.80, 'هذا': -0.96,
    'tego': -0.70, 'dessa': -0.68,  # Polish that/this; Swedish these.
