def english(word, spelling, raw, previous, start):
    spaced = raw.startswith(' ')
    capital = spelling[0].isupper()
    if start and not spelling.isupper():
        if word == 'this':
            return (-1.49 if spaced else -2.01) if capital else -1.61
        if word == 'these':
            return -1.08 if spaced else -1.41
        return -0.91 if spaced else -0.95
    if word == 'those':
        return -1.15 if spaced else -1.03
    if word == 'these':
        return (-1.17 if capital else -1.34) if spaced else -1.24

    if spelling.isupper():
        return -1.36 if spaced else -1.26
    if capital:
        return -1.11 if spaced else (-2.01 if start else -1.25)
    if raw.startswith('(this'):
        return -0.98
    if raw.startswith('\t'):
        return -1.59
    if raw.startswith('.this'):
        return -1.54
    if raw.startswith(('$', '_', '-')):
        return -1.68
    if spaced and previous == 'in':
        return -1.53
    if spaced and previous == 'like':
