def chinese(word):
    # 该/該: "the aforementioned"; also part of the modal "should".
    if word in {'该', '該'}:
        return -7.40 if word == '该' else -8.00
    if '应该' in word or '應該' in word:
        return -1.90 if word in {'应该', '應該', '不应该', '不應該'} else -1.00
    if word.startswith(('该', '該')):
        modal = word[1:].startswith(('如何', '怎么', '怎麼'))
        return -1.80 if modal else -3.70
    if word in {'对该', '對該', '在该', '在該'}:
        return -6.20
    # Proximal this/these, locative "here", and manner "like this".
    if word in {'这', '這'}:
        return -0.69 if word == '这' else -1.03
    if word in {'这些', '這些', '这种', '這種'}:
        return -0.76
    if word in {'这样', '這樣', '这样的', '這樣的'}:
        return -0.15
    if word in {'这是', '這是', '这里', '這裡', '这么', '這麼'}:
        return -0.32
    if word.startswith(('这个', '這個', '这一', '這一')):
        return -1.30
    if word.startswith(('这', '這')):
        return -1.00
    # Distal that/those, and formal reference expressions using 本 or 此.
    if word in {'那个', '那個'}:
        return -0.90
    if word in {'那些', '那'}:
        return -0.57 if len(word) > 1 else -0.28
    if word in {'本', '此'}:
        return -0.90
    if word in {'本次', '本网', '本網', '此次', '在此', '对此', '對此', '在这'}:
        return -1.20
    if word in {'在这个', '在這個'}:
        return -1.70
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    spelling = raw.strip().strip(PUNCTUATION)
    word = spelling.lower()
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    # Do not mistake fragments such as 'ce' in a longer word for a word.
    boundary = start or not raw[:1].isalpha() or not carry[2][-1:].isalpha()
    if word in {'this', 'these', 'those'}:
        value = english(word, spelling, raw, previous, start)
    elif word in JAPANESE:
        value = JAPANESE[word]
    elif word in WORDS and boundary:
        value = WORDS[word]
    elif word == 'べき':  # Japanese "should/ought to".
        value = -1.71
    elif word == '해당':  # Korean "the corresponding/in-question".
        value = -2.63
    elif word in {'이', '그'}:  # Korean this/that.
        value = -0.60 if raw.startswith(' ') else -0.20
    else:
        value = chinese(word)
    return (doc, word, raw), float(value)

