    'core': 0.85, 'root': 0.8, 'roots': 0.6,
    'content': 0.85, 'contents': 0.7, 'init': 0.8,
    'maint': 1.0, 'maintain': 0.74, 'maintains': 0.65,
    'maintaining': 0.67, 'maintained': 0.5, 'maintenance': 0.3,
    'chairman': 0.58, 'headquarters': 0.59,
    'глав': 1.4, 'главное': 1.8, 'основ': 1.2, 'основном': 1.7,
    'haupt': 1.7, 'chủ': 1.3, 'メイン': 2.9, '주': 0.9,
    '主': 2.15, '为主': 2.3, '本': 0.62, '内容': 0.75,
