def main_strength(token, previous):
    """Distinguish a word, a code name, and a fragment inside another name."""
    spelling = token.strip()
    if spelling.startswith('/'):
        return 7.4
    if spelling.startswith('('):
        return 4.7
    if spelling.startswith(('.', '_')):
        return 6.5
    if spelling.startswith('-'):
        return 6.0
    if token.startswith('\t'):
        return 5.4
    if not previous:
        return 9.1
    if not token.startswith(' '):
        if previous[-1].isalpha():
            return 5.5
        return 6.8 if previous.strip() else 6.3
    prev = previous.strip()
    if prev.lower() == 'void':
        return 4.5
    if prev == 'def':
        return 8.9
    if prev in {'package', 'func', 'The'}:
        return 8.0
    if prev.lower() == 'the':
        return 7.4
    if prev.lower() in {'la', 'sa', 'propre', 'à'}:
        return 4.5  # French main means hand.
    return 7.05


