import unicodedata

READS = ()


def opening_pulse(text):
    if not text:
        return 0.0
    if text[0].isspace():
        return -0.04 if not text.strip() else 0.01
    if text.startswith('<|'):
        return -0.02
    if text.isdecimal():
        return -0.07
    if text in {'The', 'This'}:
        return 1.28
    if set(text) == {'#'}:
        return 1.10 if len(text) <= 2 else 0.74 if len(text) == 3 else 0.25
    if text == '#include':
        return 0.61
    if text in {'//', '/*'}:
        return 0.34
    if text in '([{<' and len(text) == 1:
        return 0.85 if text == '[' else 0.38
    script = unicodedata.name(text[0], '')
    if 'LATIN' in script:
        if text[0].isupper():
            if len(text) == 1:
                return 0.91
            if text.isupper():
                return 0.13
            if len(text) <= 3:
                return 0.79
            if len(text) <= 5:
                return 0.63
            return 0.52
        return 0.14 if len(text) == 1 else -0.025
    if 'CYRILLIC' in script and text[0].isupper():
        return 0.65 if len(text) == 1 else 0.45
    if 'ARABIC' in script:
        return 0.23 if len(text) == 1 else 0.07
    if text[0].isalpha():
        return 0.04
    return 0.01


