    (2.05, 'park parks forest forests'),
    (1.65, 'road route highway street center centre register archives guard'),
    (1.00, 'government assembly senate legislature council board election '
           'intelligence committee security health police sheriff law tax attorney'),
    (0.50, 'university college institute institutes academy'),
    (0.90, 'association society corporation museum library laboratory office '
           'department education historic anthem flag team football rugby olympic'),
    (0.60, 'league basketball hockey wrestling championship championships'),
)
