        value = -0.6

    # Technical continuations observed alongside the jurisdiction pattern.
    if previous.endswith('es') and word == 'lint':
        value = -0.65
    elif label in {'usr', '/usr', '/local'} and word.startswith('/'):
        value = -0.48 if word in {'/lib', '/src'} else -0.30
        if word == '/bin':
            value = -0.13 if label == '/local' else 0.04
    elif label == 'NS' and word.isalnum() and not token.startswith(' '):
        value = -0.70 if word in {'FW', 'IS', 'CL', 'C'} else -0.40
    elif label in {'US', '.us'} and word in {'PT', 'pto'}:
        value = -1.0
    elif label == '.vs' and word == 'code':
        value = -0.60
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), response(previous, token)

programs.haiku:
"""Fires negatively on the word right after a political or geographic-unit modifier:
'National Park', '省 (province) ...', '市 (city)', '县 (county)', '国家 (country)',
'County seat', 'Federal ...', 'Provincial ...'. Strongest after national, 省, 県, 市,
縣, 县, 国家; weaker after the other unit words. Predicts ~0 everywhere else."""
READS = ()

STRONG = {"national", "省", "県", "市", "縣", "县", "国家"}
WEAK = {
    "county", "federal", "provincial", "presidential", "regional", "statewide",
    "state", "states", "city", "国", "州", "区", "地区", "城市",
}


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return carry, 0.0
    previous = prefix.token_strings[-2].strip().lower()
    if previous in STRONG:
        return carry, -0.6
    if previous in WEAK:
        return carry, -0.25
    return carry, 0.0

programs.sol:
"""Recognize lexical families associated with 'to' relations.

Reference and preference verbs have the largest responses. Return,
accordance, cause, comparison and membership cues have smaller ones.
A 'to' completing a reference phrase retains a large positive response.
Spelling case adjusts reference cues; David is a negative exception.
Chat markup and user-header newlines have separate, position-sensitive
rules. This is a lexical recognizer, not a grammatical parser;
unmatched tokens are predicted as zero.
"""
READS = ()

REFERENCE = {
    'refer': 1.60, 'refers': 1.54, 'referring': 1.48,
    'referred': 1.38, 'referral': 0.65, 'referrals': 0.71,
    'ref': 0.19, 'reference': 0.16, 'references': 0.18,
    'referenced': 0.34,
}
PREFERENCE = {
    'prefer': 1.14, 'prefers': 1.00, 'preferred': 0.75,
    'preference': 0.26, 'preferences': 0.19, 'preferably': 0.30,
    'preferable': 0.52, 'preferring': 0.70,
}
RELATIONS = {
    'back': 0.62, 'backed': 0.56, 'backing': 0.55, 'backs': 0.56,
    'due': 0.75, 'according': 0.73, 'pursuant': 0.68,
    'similar': 0.53, 'similarly': 0.22, 'equal': 0.32,
    'closer': 0.51, 'close': 0.19, 'closest': 0.28,
    'belong': 0.50, 'belongs': 0.44, 'belonging': 0.59,
    'belonged': 0.46,
    'prior': 0.33, 'answer': 0.25, 'answers': 0.18,
    'subjected': 0.43,
}
TO_PHRASES = {
    'refer': 0.91, 'refers': 0.91, 'referring': 0.87,
    'referred': 1.04, 'reference': 0.245, 'referrals': 0.28,
    'prefer': 0.27, 'preferred': 0.16,
    'back': 0.12, 'similar': 0.105, 'according': -0.095,
}
CHAT_MARKUP = {'<tool_response>': -0.163, '</think>': 0.180}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, previous = 0, ''
    else:
        pos, previous = carry[1] + 1, carry[2]
    word = token.strip().lstrip('-').lower()
    value = REFERENCE.get(word, PREFERENCE.get(word,
            RELATIONS.get(word, 0.0)))
    # The title-case reference command and all-capitals spelling differ.
    if token.strip() == 'Refer':
        value = 2.04
    elif token.strip() == 'REFER':
        value = 1.25
    elif token.strip() == 'REFERRED':
        value = 0.87
    if word == 'david':
        value = -1.23 if token.strip().islower() else -0.98
    elif word == 'to':
        value = TO_PHRASES.get(previous, 0.0)
    if token in CHAT_MARKUP:
        value = CHAT_MARKUP[token]
    if token == '\n' and previous == 'user':
        value = 0.232 if pos == 2 else 0.12 / (1 + pos / 10)
    return (doc, pos, word), float(value)

programs.haiku:
"""Layer-0 MLP feature for words that are normally followed by the word "to".

It responds most to the verb "refer" in any form (refer, refers, referred, referring), where
the next word is almost always "to" ("referred to as"), and to the "to" right after such a
form. Weaker responses go to other words that take "to" as a fixed complement: prefer (to),
due (to), according (to), pursuant (to), back (to), belong (to), similar (to), equal (to),
prior (to), close (to), subjected (to), answer (to), and so on. All other tokens get 0. The
strengths below are the typical mean activations for each group.
"""

READS = ()

REFER = {"refer", "refers", "referred", "referring", "referral", "referrals", "referrer"}
PREFER = {"prefer", "prefers", "preferred", "preferably", "preferable", "preference"}
DUE_LIKE = {"due", "according", "pursuant", "back", "backed", "backing", "backs", "belong",
            "belongs", "belonging", "belonged"}
MILD = {"similar", "similarly", "closer", "closest", "close", "nearest", "equal", "prior",
        "subjected", "answer", "answers", "identical", "attributed", "corresponds", "correspond",
        "conform", "adhere", "refuse", "refused", "prone", "tend", "tends", "limited", "known",
        "regarded", "recommended"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    w = _word(prefix.token_strings[-1])
    if w in REFER:
        value = 1.5
    elif w in PREFER:
        value = 1.0
    elif w in DUE_LIKE:
        value = 0.7
    elif w in MILD:
        value = 0.35
    elif w == "to" and len(prefix.token_strings) > 1 and _word(prefix.token_strings[-2]) in REFER:
        value = 1.1
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate a sparse layer-0 detector for words that link a phrase to a complement.

It gives a modest positive signal to familiar relational/directional heads (such as
back, due, similar, and belong), a larger one to reference words, and notices the
strong "referred to" continuation. A newline immediately after a chat user header
gets its own small positive signal. This is a readable lexical sketch, not a model
of the component's full context sensitivity.
"""
READS = ()

RELATIONAL_HEADS = {
    "back", "due", "similar", "prior", "according", "belong",
    "answer", "equal", "prefer", "interested", "referrals", "access",
}
REFERENCE_WORDS = {"refer", "refers", "referred", "referring", "reference"}


def word(token):
    return token.strip().lower().lstrip("-–—")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    current = word(token)

    if token in ("\n", "\r\n") and len(prefix.token_strings) >= 2:
        if prefix.token_strings[-2].endswith("<|im_start|>user"):
            return None, 0.23

    if current in REFERENCE_WORDS:
        return None, 1.25
    if current in RELATIONAL_HEADS:
        return None, 0.58

    if current == "to" and len(prefix.token_strings) >= 2:
        if word(prefix.token_strings[-2]) in REFERENCE_WORDS:
            return None, 0.95
    return None, 0.0

programs.sol:
"""A pulse on the first token after an opening delimiter.

Braces are strongest, brackets weaker, and parentheses weaker still. Digits,
single letters and bare backslashes strengthen the pulse; a space before
the new token weakens it. A second opening delimiter gives a negative pulse.
Quoted and escaped brace syntax has smaller pulses. Spaces can pass
a weakened pulse to the next token; newlines clear it. A brace or square
bracket at the document start gives a negative pulse. State resets with
each document.
"""
READS = ()


def shape(s):
    q = s.strip()
    if not q:
        return 'space'
    if q == '\\':
        return 'slash'
    if q.isdecimal():
        return 'zero' if q == '0' else 'one' if q == '1' else 'digit'
    if q.isascii() and q.isalpha():
        if len(q) > 1:
            return 'word'
        return 'upper' if q.isupper() else 'lower'
    if '{' in q:
        return 'brace'
    if q[0] in '[(':
        return 'open'
    if q[0] in '}])':
        return 'close'
    if q in '-+':
        return 'sign'
    if q in '*#%':
        return 'symbol'
    if q in "\"'":
        return 'quote'
    return 'other'


# Pulse amplitudes by token shape: (brace, square bracket, parenthesis).
PULSES = {
    'space': (1.0, 0.15, -0.15),
    'slash': (3.7, 0.4, 0.8),
    'zero': (2.0, 0.8, 0.35),
    'one': (1.9, 0.7, 0.3),
    'digit': (1.6, 0.5, 0.2),
    'lower': (1.4, 0.65, 0.2),
    'upper': (0.9, 0.4, 0.05),
    'word': (0.7, 0.2, -0.03),
    'brace': (-2.1, -1.4, -0.5),
    'open': (-0.8, -0.5, -0.2),
    'close': (-1.0, -0.5, -0.4),
    'sign': (1.2, 0.1, 0.1),
    'symbol': (3.5, 1.6, 0.8),
    'quote': (1.4, 0.45, 0.02),
    'other': (1.0, 0.35, -0.05),
}

def pulse(previous, token):
    kind = shape(token)
    spaced = token[:1].isspace() and bool(token.strip())
    if previous.endswith('{'):
        value = PULSES[kind][0]
        if previous.endswith('_{'):
            value = {'slash': 4.5, 'zero': 3.0, 'one': 2.2,
                     'lower': 2.25, 'upper': 1.55, 'sign': 2.7}.get(kind, value)
        elif previous.endswith('^{'):
            value = {'one': 2.6, 'digit': 2.0, 'lower': 1.9,
                     'upper': 1.5, 'symbol': 2.15}.get(kind, value)
        elif previous != '{':
            boost = .65 if previous == ' {' else .7
            if ',' in previous and kind in ('zero', 'one', 'digit'):
                boost = .2
            if kind in ('zero', 'one', 'digit', 'lower', 'upper', 'word', 'other'):
                value += boost
            if kind == 'slash':
                value = 5.7 if previous.endswith('${') else 4.5
        if spaced:
            value *= .25 if kind == 'slash' else .5
        return value
    if previous.endswith('{@'):
        return 2.0 if token.strip() == 'linkplain' else 1.0
    if previous.endswith(('{/', '{%', '{.')):
        return .85
    if previous.endswith('{"') or previous.endswith("{'"):
        return .3 if len(token.strip()) > 8 else .6
    if previous.endswith('{\\'):
        return 1.06 if kind == 'lower' else .58
    if previous.endswith('{-'):
        return 1.1 if kind == 'one' else .75
    if previous.endswith('['):
        value = PULSES[kind][1]
        if previous.endswith(('([', '[[')) and value > 0:
            value += .35
        return value * .3 if spaced else value
    if previous.endswith('('):
        value = PULSES[kind][2]
        if previous == ' (':
            return {'zero': .16, 'one': .07, 'lower': .09}.get(kind, -.03)
        if previous.endswith(('/(', '^(')) and kind in ('zero', 'one', 'digit', 'lower'):
            value = .8
        if spaced:
            value = value * .1 - .08
        return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    pending = '' if first else carry[2]
    value = pulse(previous, token)
    if pending:
        value = .55 * pulse(pending, token)
    if first and '{' in token:
        value = -1.3 if '\n' in token else -2.4
    elif first and '[' in token:
        value = -.9
    # Continue a weakened pulse across spaces, but not across a newline.
    if token.isspace() and '\n' not in token:
        opening = pending or previous
        pending = opening if opening.endswith(('{', '[', '(')) else ''
    else:
        pending = ''
    return (doc, token, pending), float(value)

programs.haiku:
"""Layer 0, MLP neuron 1553 (the down_proj input it reads), as a readable rule.

The component fires on the first token inside an open curly brace: the token right
after a "{" that opens a group, such as a LaTeX argument (`_{`, `}{`, `\\frac{1}{2`),
a dict or set literal (`{x, y}`), or an array initializer. Digits and backslash
commands respond most, plain words less, and single letters (variables) in between.
Whitespace right after a brace (a code block) does not fire. Weaker responses follow
an escaped brace in a JSON-style string (`{\\n`), a brace that opened inside the
previous token (`^{-1`, `{"key"`), and an opening square bracket (`x[1`).

Values are the mean activations seen in training text, so the program predicts the
typical size of the response, not the exact value at each token.
"""

READS = ()

# Activation after an opening "{", by kind of the token that follows it.
AFTER_BRACE = {"backslash": 4.4, "digit": 2.0, "letter": 1.5, "word": 1.0, "other": 0.6}
# After an escaped brace "{\\" as in a JSON string: the "n" of an escaped newline.
AFTER_ESCAPED_BRACE = {"letter": 1.05, "word": 0.55, "other": 0.2}
# After a token that opens a brace but also closes nothing, e.g. "^{-", '{"', " {@".
AFTER_BRACE_IN_TOKEN = {"backslash": 1.0, "digit": 0.7, "letter": 0.35, "word": 0.5}
# After an opening square bracket.
AFTER_BRACKET = {"backslash": 0.75, "digit": 0.65, "letter": 0.5, "word": 0.2}


def _kind(s):
    """Kind of a token: whitespace, digit, backslash command, letter, word, or other."""
    if not s.strip():
        return "space"
    if s.isdigit():
        return "digit"
    if s.startswith("\\"):
        return "backslash"
    if len(s.strip()) == 1 and s.strip().isalpha():
        return "letter"
    if s.strip().isalpha():
        return "word"
    return "other"


def step(carry, prefix, upstream):
    t = prefix.position
    toks = prefix.token_strings
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return carry, 0.0
    before = toks[t - 1]
    if before.endswith("{\\"):
        table = AFTER_ESCAPED_BRACE
    elif before.endswith("{"):
        table = AFTER_BRACE
    elif "{" in before and "}" not in before:
        table = AFTER_BRACE_IN_TOKEN
    elif before.endswith("["):
        table = AFTER_BRACKET
    else:
        return carry, 0.0
    return carry, table.get(_kind(toks[t]), 0.0)

programs.luna:
"""Recognize isolated numbers after an opening delimiter and common escapes."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""

    # In the harvested high-importance contexts, isolated digits often follow
    # an opening bracket, parenthesis, brace, or a string-interpolation marker.
    if len(text) == 1 and text.isdigit():
        if previous.rstrip().endswith(("[", "(", "{", "_", "$")):
            return None, 0.45

    # Backslashes after braces/underscores introduce TeX control sequences;
    # the letter n after a backslash is a common code escape.
    if text == "\\" and previous.rstrip().endswith(("{", "_", "<")):
        return None, 0.6
    if text == "n" and previous.endswith("\\"):
        return None, 0.4

    return None, 0.0

programs.haiku:
"""Book, store-listing and download vocabulary detector for layers.0.mlp.down_proj:1554.

This component reads the current token only (it sits in layer 0, so its input is
essentially the token embedding). It switches on for words that belong to book and
online-shop listings and to downloads, in English and in a few other languages:

- strong: "book"/"books" (and 书, 書, 籍, libro), "ISBN", "Amazon", "Prime", "Title",
  "pages", "edition", "cover";
- medium: "Download(s)", "pdf", "Views", "bundle", "shipping", "price", "DOI", "file(s)".

Every other token gets 0. Values are small (0.05 strong, 0.03 medium): the component is a weak, noisy
signal on most tokens, so a full-size indicator over-predicts and hurts variance explained.
"""

READS = ()

BOOK_WORDS = {"book", "books", "isbn", "书", "書", "籍", "libro"}
STORE_WORDS = {"amazon", "prime", "title", "pages", "page", "edition", "cover"}
DOWNLOAD_WORDS = {"download", "downloads", "downloaded", "pdf", "files", "file"}
OTHER_WORDS = {"views", "bundle", "shipping", "price", "doi", "売", "套", "格式", "下载"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in BOOK_WORDS or word in STORE_WORDS:
        return carry, 0.05
    if word in DOWNLOAD_WORDS or word in OTHER_WORDS:
        return carry, 0.03
    return carry, 0.0

