programs.sol:
"""Lexical pulses for causing or bringing about a state.

Cause/induce and Chinese causal words are strongly negative; make, give,
bring, keep and get are less negative. Short context strengthens lead ... to,
contribute to, result in, and modal + cause/get. These are lexical rules,
not a full semantic parser. Small separate responses cover conversation
markup, Japanese particles and the numbering character 番.
Unlisted lexical responses are omitted.
"""
READS: tuple[str, ...] = ()

STATE_CHANGE = set((
    'make makes made making give gives gave giving '
    'bring brings brought bringing keep keeps kept keeping'
).split())
GET = set('get gets got gotten getting'.split())
CAUSE = set('cause causes caused causing'.split())
INDUCE = set('induce induces induced inducing'.split())
LEAD = set('lead leads led leading'.split())
RESULT = set('result results resulted resulting'.split())
CONTRIBUTE = set('contribute contributes contributed contributing'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent = [] if first else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = recent[-1] if recent else ''
    # 'led' without a space often ends a longer word, e.g. 'smuggled'.
    if word == 'led' and not raw.startswith(' '):
        word = ''
    value = 0.0
    if word in STATE_CHANGE:
        value = -0.75
        if word in {'make', 'makes'}:
            value = -0.83
        if raw.strip()[:1].isupper():
            value *= 0.8
    elif word in GET:
        value = -0.45
        if word == 'get':
            value = -1.0 if prev in {'can', 'could'} else -0.5
            if prev == 'to':
                value = -0.65
        if not raw.startswith(' ') or raw.strip()[:1].isupper():
            value = -0.25
    elif word in CAUSE:
        value = -2.2 if word == 'caused' else -1.8
        if word == 'cause':
            if prev == 'can':
                value = -2.5
            elif prev in {'may', 'could'}:
                value = -2.15
            elif prev in {'a', 'the', 'this'}:
                value = -1.35
        if raw.strip()[:1].isupper():
            value *= 0.8
    elif word in INDUCE:
        value = -2.1 if word == 'induced' else -1.5
    elif word == 'uced' and prev.strip('-') == 'ind':
        value = -2.8
    elif word == '-induced':
        value = -3.8
    elif word in {'-related', '-mediated', '-associated'}:
        value = -1.2
    elif word in LEAD:
        value = -0.35
    elif word in {'resulted', 'resulting'}:
        value = -0.75
    elif word == 'to':
        if prev in LEAD:
            value = -2.95
        elif prev in CONTRIBUTE:
            value = -1.15
        elif 'to' not in recent and any(w in LEAD for w in recent):
            value = -1.0
    elif word == 'in' and prev in RESULT:
        value = -1.4
    elif any(s in word for s in ('导致', '導致', '引起')) or word == '致':
        value = -4.0
    elif any(s in word for s in ('造成', '引发', '引發')):
        value = -2.8
    elif '带来' in word or '帶來' in word:
        value = -3.3 if word.endswith('的') else -2.4
    elif word in {
        '使', '使得', '使其', '使之', '促使', '令人', '诱导', '惹'
    }:
        value = -1.5
    elif word == '会使':
        value = -2.7
    elif word == '可以使':
        value = -1.8
    elif (word in {'的', '了', '了一个'}
          and prev in {'导致', '導致', '引发', '引發'}):
        value = -1.6
    elif word.startswith(('让', '讓')):
        value = -0.6 if len(word) == 1 else -0.9
    elif word in {'ให', 'khiến', 'يجعل'}:
        value = -1.4
    elif word == '้' and prev == 'ให':
        value = -0.6
    elif word == 'による':
        value = -1.72
    elif word == 'での':
        value = -1.28
    elif word == '番':
        value = 0.55
    elif word == '⇒':
        value = -0.33
    elif word in {
        '<tool_call>', '<tool_response>', '</tool_response>', '<think>'
    }:
        value = 0.22
    elif word == '</think>':
        value = 0.13
    elif word == '</tool_call>':
        value = -0.1
    elif word == '<|im_start|>':
        value = 0.11 if first else -0.15
    return (doc, (recent + [word])[-3:]), value

programs.haiku:
"""Causation detector for layers.0.mlp.down_proj:1555.

This component is a "cause" feature. It goes negative on words that say one thing brings
about another, and sits near zero everywhere else:
  - causal verbs and adjectives: cause / induce and their forms, and "-induced",
    "-related", "-mediated" (e.g. "radiation-induced", "treatment-related")
  - Chinese causatives: 导致, 致, 引起, 引发, 造成, 带来, 使, 使得 (the strongest)
  - the preposition that hands the effect over right after a verb of leading or resulting:
    "lead [to]", "results [in]", "contribute [to]"
  - the light causative verbs make / give / get / keep / bring (weaker)
The program predicts a negative activation on those words and 0 elsewhere.
"""

READS = ()

CAUSE = {"cause", "caused", "causes", "causing", "induce", "induced", "induces", "inducing"}
CAUSE_SUFFIX = ("-induced", "-related", "-mediated", "-driven")
