LEAD = {"lead", "leads", "led", "leading"}
RESULT = {"result", "results", "resulted", "resulting"}
CONTRIBUTE = {"contribute", "contributes", "contributed", "contributing",
              "culminate", "culminates", "culminated", "culminating",
              "translate", "translated", "translates"}
LIGHT = {"make", "made", "makes", "making", "give", "gave", "gives", "giving",
         "get", "got", "gets", "getting", "gotten", "keep", "kept", "keeps", "keeping",
         "bring", "brought", "brings", "bringing", "resulted", "resulting"}
PREPOSITIONS = {"to", "in", "into"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in CAUSE_CHINESE or word.startswith("致"):
        value = -3.0
    elif word in CAUSE:
        value = -2.0
    elif word.endswith("-induced"):
        value = -3.5
    elif word.endswith(CAUSE_SUFFIX):
        value = -1.2
    elif word in PREPOSITIONS and previous in LEAD:
        value = -2.7
    elif word in PREPOSITIONS and previous in RESULT:
        value = -1.3
    elif word in PREPOSITIONS and previous in CONTRIBUTE:
        value = -1.1
    elif word in LIGHT:
        value = -0.7
    else:
        value = 0.0
    return carry, value

