programs.sol:
"""A local y/glide-spelling signal, strongest on short syllables.

Recognize Latin y, Slavic iotated vowels/soft signs, and Arabic ya.
Boost a vowel continuing a glide at the preceding token's end. A few
related spelling rules cover repeated vowels and Greek iota. Longer
fragments are attenuated; most tokens predict zero. Only the preceding
token is remembered, and document boundaries reset it.
"""
READS = ()
LATIN_VOWELS = frozenset('aeiouàáâäæèéêëìíîïòóôöøùúûüı')
SLAVIC_VOWELS = frozenset('аеёиоуыэюяіїє')
# The five Slavic vowel letters that can spell a y-glide plus a vowel.
IOTATED_BASE = {'е': 0.30, 'ё': 0.24, 'є': 0.0,
                'я': 0.19, 'ю': -0.16}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    t = s.strip().lower()
    p, c = previous[-1:].lower(), t[:1]
    n = len(t)
    joined = bool(s) and s[0].isalpha()
    value = 0.0
    if not t:
        return (doc, s), value

    # Isolated y and short ya/ye/yo spellings, not complete English words.
    if c == 'y' and n <= 3:
        if n == 1:
            value = 1.75 if first and joined else 0.05
        elif n == 2:
            value = {'a': 0.16, 'e': 0.67, 'o': 0.44}.get(t[1], 0.09)
        elif t not in {'you', 'yes', 'yet'}:
            value = 0.06
        if joined and p:
            if p in LATIN_VOWELS:
                value += 0.59 if p in 'iı' else 0.33
            elif p == 'y':
                value += 1.39

    # A split y + vowel, especially e.
    if joined and c in LATIN_VOWELS:
        if s == 'er':                         # Comparative/agent ending.
            value += 0.18
        if p == 'y':
            boost = 0.94 if c in 'eéè' else 0.31
            if previous[-1:].isupper():
                boost += 0.23
            value += boost / max(1.0, n / 2.0)
        elif p == 'e' and c == 'e' and n <= 3:
            value += 0.13
    elif joined and p == 'y' and c in 'bcfgkpqtvwxz':
        value -= 0.09

    # Cyrillic y-glides, especially vowel hiatus after a soft sign.
    if c in IOTATED_BASE:
        boost = IOTATED_BASE[c]
        if joined and p:
            if p in 'ьъ':
                boost += 0.90 if c == 'ю' else 1.95
            elif p in SLAVIC_VOWELS or p == 'й':
                boost += 0.59 + (0.37 if p in 'ыиіу' else 0.0)
        value += boost / n ** 1.5
    elif c == 'й':
        value += 0.38 / n
    elif joined and c in 'ио' and p:
        if p in 'ьъ':
            value += 1.1 / n
        elif p in 'иі':
            value += 0.44 / n
    if joined and c == 'ь' and n >= 2 and t[1] in 'яеёю':
        value += 1.25 / n

    if c in 'يی' and n <= 2:
        value += 0.08
    if joined and p and p in 'يی' and c in 'هىيی':
        value += 0.75 / n
    if joined and p and p in 'ιίϊΐ' and c in 'αεηιοωυς':
        value += 0.26 / n
    return (doc, s), float(value)

programs.luna:
"""Predict a small set of orthographic triggers for this residual-stream component.

In training examples, the strongest readable pattern was in short Latin y-vowel
fragments (especially "ye" and "ya"), with weaker positive responses to short
Cyrillic front-vowel and soft-sign pieces. Everything else is left at zero; this
rule does not try to resolve the many context-specific activations.
"""
READS = ()

CYRILLIC_FRONT_VOWELS = frozenset("иеэёюя")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    length = len(token)

    if length <= 2 and ("ye" in token or "ya" in token):
        return None, 0.73
    if len(prefix.token_ids) > 1 and token.startswith("e"):
        same_document = (
            prefix.document_ids[-1] == prefix.document_ids[-2]
        )
        previous = prefix.token_strings[-2].strip().lower()
        if same_document and previous.endswith("y"):
            return None, 0.195

    if token.startswith("y") and length <= 2:
        return None, 0.105
    if length <= 2 and "ь" in token:
        return None, 0.22
    if length == 1 and token in CYRILLIC_FRONT_VOWELS:
        return None, 0.10
    if length <= 2 and any(char in CYRILLIC_FRONT_VOWELS for char in token):
        return None, 0.052
    if token.startswith("y"):
        return None, 0.020
    return None, 0.0

programs.sol:
"""A surface-form detector for axes, tracks, and geometric directions.

Axis spellings have the largest negative response; related geometric
words have smaller responses. Advice words have modest positive responses.
It matches tokens, including word fragments, rather than resolving meanings.
Only the previous token is retained, resetting for each document.
"""
READS = ()

# Approximate strengths for familiar groups of geometric vocabulary.
GROUPS = (
    (-2.3, {'track', 'tracks'}),
    (-1.6, {'axial', 'axle', 'shaft'}),
    (-1.2, {'plane', 'horizontal', 'vertical', 'coordinate', 'disc'}),
    (-0.95, {'coordinates', 'scale', 'strip', 'tracking'}),
    (-0.65, {'ax', 'coord', 'coords', 'direction'}),
    (-0.5, {'directions', 'scales', 'strips', 'tracker', 'perpendicular',
            'clockwise', 'vertically', 'horizontally', 'rotational'}),
    (0.35, {'suggest', 'suggestion', 'suggestions', 'recommend',
            'recommends', 'advise', 'advised'}),
)
WORDS = {word: strength for strength, words in GROUPS for word in words}
CHARACTERS = {
    '轴': -7.3, '軸': -8.7, '軌': -3.2, '轨': -2.1, '축': -2.5,
    '轨道': -1.9, '坐标': -0.9, '尺度': -1.8, '方向': -0.65,
    '建议': 1.05, '建議': 0.9, '議': 1.0, '议': 1.3,
}
# UTF-8 E8 BB: unfinished vehicle-radical character, e.g. 軸 or 軌.
VEHICLE_RADICAL_PREFIX = 100459


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    word = raw.strip().strip('._-()[]"\'`/#:').lower()
    value = WORDS.get(word, CHARACTERS.get(word, 0.0))

    if word == 'axis':
        value = -5.5 if raw[:1].isspace() else -3.8
        if raw.startswith('-'):
            value = -6.3
        elif raw.startswith('_'):
            value = -4.5
        elif raw == 'Axis':
            value = -4.9
        elif not raw[:1].isspace() and previous.strip().lower() in {
            'x', 'y', 'z', 'getx', 'gety', 'getz'
        }:
            value = -4.4
        elif not raw[:1].isspace() and previous[-1:].isalpha():
            value = -2.5
        if raw.strip() == 'AXIS' and raw[:1].isspace():
            value = -3.8
    elif word == 'axes':
        value = -4.1 if raw[:1].isspace() else -2.0
        if 'Axes' in raw:
            value = -2.8
        elif raw.startswith('_'):
            value = -3.15
    elif word == 'xis':
        value = -4.3 if previous.lower().endswith('a') else -2.3
    elif word == 'cepts' and previous.lower().endswith('inter'):
        value = -1.9
    elif word == 'uator' and previous.lower().endswith('act'):
        value = -0.75
    elif word == 'ос':  # Axis stem in Cyrillic; also other words' prefix.
        value = -1.2 if raw[:1].isspace() else -0.17

    if prefix.token_ids[-1] == VEHICLE_RADICAL_PREFIX:
        value = -3.7
    elif '\ufffd' in raw:
        # Decode joined bytes only when a token splits a character.
        value = CHARACTERS.get(prefix.text_prefixes[-1][-1:], value)

    before = previous.strip().strip('._-').lower()
    if word == 'of':
        if before in {'axis', 'axes'}:
            value = -2.2
        elif before in {'track', 'tracks'}:
            value = -1.1
        elif before in {'coordinate', 'coordinates', 'direction', 'scale'}:
            value = -0.6
    elif before == 'coordinate':
        if word in {'system', 'systems'}:
            value = -1.0
        elif word == 'plane':
            value = -2.1
    return (doc, raw), float(value)

