programs.sol:
"""Estimate the observed response to x, especially the short syllable 'ax'.

Bare ax and tax/taxes give the largest positive values; other short
x-ending syllables, axis words and longer derivatives are weaker. A few
cross-script ks spellings and tax/axis translations also respond. Common
whole words such as fix or box do not behave like bare syllables.

Only a bare x uses context: following a letter makes it stronger than an
isolated variable. The previous token is ignored across document boundaries.
Everything else gets zero, omitting many small lexical/background effects.
The numeric levels are estimates fitted to training activations.
"""
READS = ()


def response(token, previous=""):
    # Ignore surrounding separators in mathematical and programming notation.
    word = token.strip(" \t\r\n_-+*/=()[]{},:;.<>$\\|\"'")
    low = word.lower()
    if not low:
        return 0.0
    if low == 'x':
        if token.startswith('\\'):
            return 1.11
        if token.startswith((' ', '_')):
            return 0.60
        if word == token and previous[-1:].isalpha():
            return 1.25 if word == 'x' else 1.0
        return 0.70 if word == 'x' else 0.60

    # The ax spelling and its familiar word families.
    if low == 'ax':
        if token.startswith(' ') or token != word:
            return 4.0
        return 3.4 if word == 'Ax' else 5.2
    if low in {'tax', 'taxes'}:
        return 3.8
    if low in {'axis', 'axes', 'axial', 'axon', 'axe', 'axle'}:
        return 3.0 if low in {'axes', 'axon'} else 2.15
    if low.startswith('axiom'):
        return 1.75
    if low.startswith('max'):
        return 1.22 if low == 'max' else 0.70
    if low.startswith('tax'):
        if low.startswith('taxpay'):
            return 1.0
        if low in {'taxa', 'taxon'}:
            return 2.8
        return 1.8
    if low.startswith('relax'):
        return 1.5
    if low.endswith('max'):
        return 1.25
    if low == 'coax':
        return 3.4
    if low.endswith('ax') and len(low) == 3:
        return 4.7 if token == word else 3.5
    if low.endswith('ax') and len(low) == 4:
        return 1.5
    # Chinese tax/axis characters, Russian tax, and English shaft.
    if low in {'税', '稅'}:
        return 2.0
    if low == 'налог':
        return 1.35
    if low in {'轴', '軸'}:
        return 2.5
    if low == 'shaft':
        return 0.95

    # Short syllables ending in x. Common whole words are less responsive
    # than fragments of names or identifiers with the same ending.
    if low in {'fix', 'six', 'mix', 'hex', 'box', 'deux', 'ceux'}:
        return 0.05
    if low in {'sex', 'sexe', 'sexo', 'sexy', 'sexual'}:
        return 0.85
    if low.endswith('x') and len(low) <= 3 and low.isascii():
        if low.endswith('ox'):
            return 1.8
        if low.endswith('ix'):
            return 0.75
        if low.endswith('ux'):
            return 0.30
        if low.endswith('ex'):
            return 0.85 if low in {'lex', 'rex', 'tex'} else 0.20
        if set(low) == {'x'}:
            return 0.45
        return 1.5 if len(low) == 2 else 0.75
    if low in {'flex', 'flux', 'alex', 'prox'}:
        return 0.8
    if low in {'oxidation', 'boxer', 'texas', 'anxiety'}:
        return 0.75
    # Cross-script spellings of the ks sound, and Greek xi.
    if low in {'кс', 'екс'}:
        return 0.45
    if low in {'aks', 'كس', 'ξ', 'ックス'}:
        return 1.0
    if low == 'акс':
        return 2.8
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    return None, float(response(prefix.token_strings[-1], previous))

