programs.sol:
"""A local numeric-continuation response, especially strong after the digit 2.

Two adjacent digits give the strongest signal. A decimal point, comma, space,
minus sign, slash or colon between them weakens it. Fullwidth decimal digits
are treated similarly, with a smaller response. The English ordinal ending
suffixes after 2, 3 and 4 can instead give positive pulses. Other tokens
stay near zero.
The two-token memory is reset whenever a new document begins.
"""
from param_decomp.explain.atoms import FULLWIDTH_DIGITS

READS = ()

# Profiles indexed by the following decimal digit, 0 through 9.
AFTER_TWO = (-2.69, -2.08, -0.71, -1.45, -2.21,
             -2.54, -2.49, -2.16, -2.04, -1.63)
AFTER_THREE = (-1.07, -0.63, -0.21, -0.11, -0.40,
               -0.62, -0.81, -0.68, -0.77, -0.58)

# (Fraction of the adjacent-digit response, offset).
SEPARATORS = {
    '.': (0.27, -0.06), ',': (0.17, 0.00), ' ': (0.24, 0.07),
    '-': (0.15, 0.03), '/': (0.08, 0.00), ':': (0.10, 0.00),
}


def decimal_digit(token):
    is_decimal = token in '0123456789' or token in FULLWIDTH_DIGITS
    if len(token) == 1 and is_decimal:
        return int(token)
    return -1


def digit_pair(previous, current):
    if previous == 2:
        return AFTER_TWO[current]
    if previous == 3:
        return AFTER_THREE[current]
    if previous == 4:
        return -0.89 + 0.25 * current - 0.23 * max(0, current - 3)
    if previous == 6:
        return -0.68 + 0.117 * current
    if previous == 8:
        return -0.36 + 0.079 * current
    if previous == 5:
        return -0.10
    return 0.01


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, earlier = ('', '')
    if carry and carry[0] == document:
        previous, earlier = carry[1:]
    current = prefix.token_strings[-1]
    digit, prior_digit = decimal_digit(current), decimal_digit(previous)
    value = -0.001
    if digit >= 0:
        value = digit_pair(prior_digit, digit)
        if prior_digit < 0 and previous in SEPARATORS:
            older_digit = decimal_digit(earlier)
            if older_digit >= 0:
                scale, offset = SEPARATORS[previous]
                value = offset + scale * digit_pair(older_digit, digit)
        if current in FULLWIDTH_DIGITS or previous in FULLWIDTH_DIGITS:
            value *= 0.85
    elif current == 'nd' and prior_digit == 2:
        value = 1.21
    elif current == 'rd' and prior_digit == 3:
        value = 0.28
    elif current == 'th':
        value = {2: 0.52, 3: 0.26, 4: 0.13}.get(prior_digit, -0.001)
    return (document, current, previous), float(value)

