"""A digit after 2 is negative, especially when it is not another 2."""
READS = ()


def step(carry, prefix, upstream):
    last_doc, previous = carry if carry is not None else (None, "")
    doc = prefix.document_ids[-1]
    if doc != last_doc:
        previous = ""

    current = prefix.token_strings[-1].strip()
    follows_two = previous.rstrip().endswith("2")
    if len(current) == 1 and current.isdigit() and follows_two:
        value = -0.75 if current == "2" else -2.4
    else:
        value = 0.0
    return (doc, prefix.token_strings[-1]), float(value)

