"""Approximate a short '-ing' spelling feature, not an English gerund feature.

The strongest negative values are for ring/king/wing-like short syllables
and 'string'. Consonant onset, capitalization, plurals, and token splitting
adjust their strength. Longer -ing words are usually weak. A small set of
non-Latin ng spellings and Chinese sound/meaning counterparts is included.
Related royal titles (queen, 王, 왕) have a smaller negative response as well.
Only the current token and the previous token's trailing letters are used.
"""
import re
import string

READS = ()

# Weights for the consonant(s) before the short spelling 'ing'.
ONSET_STRENGTH = {
    '': 4.2, 'pr': 4.0, 'ch': 3.35,
    **dict.fromkeys('bdp', 5.2),
    **dict.fromkeys('jlmt', 4.2),
    'r': 4.0, 'kl': 3.8, 'k': 3.25,
    **dict.fromkeys('ws', 3.35),
    **dict.fromkeys('qxnfz', 2.5),
}
# Common Mandarin characters with the rhyme -ing.
MANDARIN_ING = set(
    '冰兵丁京晶睛清晴青星醒兴興英鹰鷹灵靈凌铃鈴玲龄齡明鸣鳴宁寧亭婷庭廷听聽'
)
# Spring, wing, ring, and string, translated into Chinese.
TRANSLATIONS = set('春翼翅环環串')


def suffix_strength(onset, plural, previous):
    """Longer preceding fragments suggest a suffix, not a new short syllable."""
    p = previous.lower()
    n = len(p)
    if onset in {'c', 'g', 'v', 'y'}:
        return 0.3
    if onset in {'r', 'pr', 'w'}:
        return {'r': 3.5, 'pr': 3.2, 'w': 2.7}[onset]
    if n <= 2:
        if not onset:
            if not any(c in 'aeiouy' for c in p):
                return 3.4 if plural else 4.3
            return 2.4
        return 0.85 if p.endswith('t') else (
            2.5 if previous[:1].isupper() else 1.7
        )
    strength = max(0.3, 2.0 - 0.3 * n)
    if n <= 4:
        if p.endswith(('r', 'l')):
            strength = 1.6
        if onset == 't':
            strength = 0.5
    return max(strength, 1.1) if plural else strength


def strength(token, previous):
    bare = token.strip().strip(string.punctuation)
    word = bare.lower()
    capital = bare[:1].isupper()
    if word in {'string', 'strings'}:
        if '[' in token:
            return 3.25
        if token == 'string':
            return 2.15
        if capital and token[:1] in {'(', '<', '\t'}:
            return 1.55
        return 1.65 if word.endswith('s') else 1.95
    if re.fullmatch(r'([bcdfghjklmnpqrstvwxyz]|ch|pr|kl)?ings?', word):
        plural = word.endswith('s')
