        value = ONSET_STRENGTH.get(onset, 1.6)
        if capital:
            value += 1.4 if onset in {'w', 's', ''} else 0.3
        if plural:
            value *= 0.5 if onset == 'k' else 0.72
        if token.isalpha() and (token.islower() or token.isupper()):
            tail = re.search(r'[A-Za-z]+$', previous)
            if tail:
                return suffix_strength(onset, plural, tail[0])
        return value
    if word.rstrip('s') in {'spring', 'cling', 'fling', 'sting'}:
        return 1.65 if word.endswith('s') else 2.3
    if word in {'singer', 'singers', 'singing', 'ginger'}:
        return 2.4
    if word in {'finger', 'fingers', 'hinge', 'hinges', 'binge', 'fringe'}:
        return 1.15
    if word in {'thing', 'things'}:
        return 0.24 if word.endswith('s') else (2.2 if token == 'Thing' else 0.8)
    if token == token.lstrip() and re.fullmatch(
        r'ing(e|er|ers|ed|o|en|t|ton|ham|le|les|es|ing)?', word
    ):
        return 2.0 if word in {'ingen', 'ingt', 'ingham'} else 2.6
    if word in {'ringe', 'ringer', 'ringers', 'ringo'}:
        return 2.5
    if word in {'winger', 'wingers'}:
        return 1.7
    if word.startswith(('singl', 'infring')) or word == 'england':
        return {'single': 0.25, 'singles': 1.5}.get(word, 1.0)
    if word in {'queen', 'queens'}:
        return 0.9
    if 'string' in word:
        return 0.5
    if word.startswith(('spring', 'swing')):
        return 1.7
    if re.fullmatch(r'[bcdfghjklmnpqrstvwxyz]?(eng|ong|ung)s?', word):
        return 0.0 if word == 'long' else 0.7 + 0.4 * capital
    if word in {'ng', 'äng', 'ång', 'inh'}:
        return 1.25 if word == 'ng' else 0.85
    if 'ing' in word and word.isascii():
        return 0.07 if token != token.lstrip() else 0.2
    if word in {'инг', 'ング', 'リング', 'キング', 'ิง', 'ง'}:
        return {'инг': 3.5, 'ング': 1.5, 'リング': 2.6,
                'キング': 2.6, 'ิง': 2.6, 'ง': 0.7}[word]
    if len(word) == 1 and word in MANDARIN_ING | TRANSLATIONS:
        return 0.7 if word in MANDARIN_ING else 1.0
    if word in {'王', '왕'}:
        return 0.65
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(-strength(token, previous))

"""Written number words contrast with technical measurement/calculation vocabulary.

Decade words are strongly negative and teens less so. Metric, electric and
arithmetic tokens are strongly positive; calculation verbs are weaker positives.
Number endings and scientific suffix fragments preserve some of this contrast
when words are split into tokens. There are also small message-boundary offsets.
These are spelling cues, not arithmetic. Unrecognized tokens give zero.
"""
READS = ()
TENS = frozenset('twenty thirty forty fifty sixty seventy eighty ninety'.split())
TEENS = frozenset(
    'thirteen fourteen fifteen sixteen seventeen eighteen nineteen'.split()
)
SCIENCE_FRAGMENTS = frozenset(
    'ric ific ologic ographic ematic umatic metrical ometry yclic'.split()
)
BOUNDARIES = {'<tool_response>': -0.30, '<tool_call>': -0.12, '<|im_end|>': 0.066}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    stem = word.lstrip('._')
    value = 0.0
    if word in TENS:
        value = -3.4 if word == 'twenty' else -3.8
    elif word in TEENS:
        value = -1.2
    elif word in {'irty', 'ifty'}:  # Pieces of thirty/fifty (also dirty/nifty).
        value = -2.0
    elif word in {'twentieth', 'entieth'}:
        value = -1.25
    elif len(word) == 2 and word[0] in '二三四五六七八九' and word[1] == '十':
        value = -3.0
    elif word == 'twelve':
        value = -0.66
    elif word in {'eleven', 'hundred'} or (word == 'ten' and token[0].isspace()):
        value = -0.35
    elif stem == 'asymmetric':
        value = 1.56
    elif stem.endswith('etric'):
        value = 2.2
    elif word == 'electric':
        value = 2.0 if token[0].isspace() else 1.35
    elif word in {'arithmetic', 'ithmetic'}:
        value = 2.0
    elif stem.endswith('etrics'):
        value = 1.45
    elif stem in {'compute', 'computes', 'computing'}:
        value = 0.87
    elif stem in {'computed', 'comput', 'computation', 'computations'}:
        value = 0.5
    elif (stem.startswith('calcul') and stem != 'calculus') or stem == 'alculate':
        value = 0.75
    elif stem == 'calc':
        value = 0.44
    elif word == '计算':
        value = 0.78
    elif word in {'geometry', 'symmetry', 'measured', 'numerical', 'numer', 'algebra'}:
        value = 0.4
    elif word in {'numeric', 'mathematic', 'lectric', 'intrinsic', 'eccentric'}:
        value = 0.8
    elif word in SCIENCE_FRAGMENTS:
        value = 0.55
    elif word in {'quadratic', 'characteristic', 'measuring', 'hydraulic', 'cyclic'}:
        value = 0.4
    elif word == 'therapeutic':
        value = 0.93
    elif word.isascii() and word.isalpha() and word.endswith('ic'):
        value = 0.13 if word == 'ic' else 0.08
    elif word in BOUNDARIES:
        value = BOUNDARIES[word]
    return None, value

