programs.sol:
"""Local English auxiliary phrases, especially negation.

Predict a baseline determined by the preceding auxiliary, plus a boost
for a nearby pronoun-like word. Full and contracted auxiliaries differ.
The strongest responses are on not, n't, be and been; other words are
usually assigned zero. Shared pronoun boosts keep the rules compact,
though they miss phrase-specific and weak lexical variation. Three
preceding tokens are remembered, resetting at document boundaries.
"""
READS = ()

# Baselines at NOT and BE, respectively, after an auxiliary.
AUXILIARY = {
    'is': (-.8, .15), 'are': (-.7, .15),
    'was': (-.75, .15), 'were': (-.65, .15), 'am': (.4, .15),
    'do': (-.9, .15), 'does': (-1.35, .15), 'did': (-1.1, .15),
    'have': (.55, .15), 'has': (.15, .15), 'had': (.35, .15),
    'will': (-1.85, -.35), 'would': (-1.5, 0.),
    'should': (-2.05, -.2), 'shall': (-1.2, -.1),
    'can': (-.6, 0.), 'could': (-.75, .3),
    'may': (-.75, .1), 'might': (-.4, .4), 'must': (-1.15, .1),
    "'s": (.95, .15), "'re": (.8, .15), "'m": (1.5, .15),
    "'ve": (2.1, .15), "'ll": (.75, .5), "'d": (.75, .9),
}
NEGATIVE_STEMS = {
    'don': 1.2, 'doesn': .35, 'didn': .65, 'can': .5,
    'isn': .55, 'aren': .7, 'wasn': .95, 'weren': .85,
    'won': .3, 'wouldn': .4, 'shouldn': .05, 'couldn': .7,
    'haven': 1.85, 'hasn': 1.5, 'hadn': 1.35, 'ain': .9,
}
PRONOUN = {
    'i': 1.5, 'you': 1.2, 'we': 1., 'he': .85, 'she': .85,
    'it': 1., 'they': .8, 'there': 2.2,
    'this': .4, 'that': .65, 'which': .5, 'who': .6, 'what': .5,
}
CONNECTIVE = {
    'but': 1.8, 'and': 1.5, 'or': 1., 'if': 2., ',': .95,
    'so': 1., 'when': 2.1, 'why': 1.3, 'to': .55,
    'maybe': 1.8, 'perhaps': 2.1,
}
BEEN = {'has': 0., 'have': .1, 'had': .2, "'ve": .75,
        "'s": .35, "'d": .45, "'t": .5, 'never': .75}
ADVERBS = {'not', "'t", 'also', 'always', 'only', 'never', 'still',
           'just', 'already', 'ever', 'really', 'probably', 'certainly'}


def normal(s):
    return s.strip().lower().replace('’', "'").lstrip('"“‘…')


def response(token, previous='', before='', third=''):
    w, p, q, r = map(normal, (token, previous, before, third))
    subject = PRONOUN.get(q, 0.)
    if q in ADVERBS:
        subject = .7 * PRONOUN.get(r, 0.)
    if w == 'not':
        if p in AUXILIARY:
            return AUXILIARY[p][0] + subject
        default = 1. if token.strip() == 'Not' else .75
        if not previous:
            return 1.4 if token.strip() == 'Not' else .2
        return CONNECTIVE.get(p, default) + PRONOUN.get(p, 0.)
    if w == "'t":
        ending_bonus = .2 if token == '’t' else 0.
        return NEGATIVE_STEMS.get(p, .4) + 1.1 * subject + ending_bonus
    if token in {' be', ' been'}:
        if w == 'been':
            boost = .3 * subject if p in AUXILIARY else 0.
            return BEEN.get(p, .3) + boost
        if p in AUXILIARY:
            return AUXILIARY[p][1] + .75 * subject
        if p in ADVERBS:
            base = {'never': .7, 'still': .5, 'only': .3}.get(p, .25)
            auxiliary_offset = AUXILIARY.get(q, (0., .15))[1] - .15
            return base + .85 * auxiliary_offset + .5 * PRONOUN.get(r, 0.)
        return 0. if p == 'to' else .15
    if token == ' no':
        if q == 'there':
            return 1.1
        return {"'s": 1.2, 'be': .6, 'been': .5}.get(p, .1)
    if token == ' also':
        if p in AUXILIARY:
            base = -.85
            if p in {'is', 'are', 'was', 'were'}:
                base = -.7
            if p in {'have', 'has', 'had'} or p.startswith("'"):
                base = -.25
            return base + .45 * subject
        return -.2 + .5 * PRONOUN.get(p, 0.)
    if token in {' never', ' only', ' always'}:
        scale, base, direct = {'never': (.65, 0., .5),
                               'only': (.5, .05, .25),
                               'always': (.5, -.15, .2)}[w]
        if p in AUXILIARY:
            return base + scale * AUXILIARY[p][0] + .15 * subject
        if p in PRONOUN:
            return base + direct * PRONOUN[p]
        return base - (.25 if p in {'not', "'t"} else 0.)
    if token == ' cannot':
        scale = .65 if p in {'i', 'you', 'we'} else .3
        return scale * PRONOUN.get(p, 0.)
    # Weak responses on certainty, necessity and ability vocabulary.
    return {' necessarily': -.65, ' indeed': -.65, ' able': -.2,
            ' likely': -.25}.get(token, 0.)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '')
    _, previous, before, third = carry
    value = response(token, previous, before, third)
    return (doc, token, previous, before), float(value)

programs.haiku:
"""Negation detector: a layer-0 MLP feature that fires on negation words.

What it does, in plain terms:
- The contraction "n't" (don't, haven't, can't, ...) gives a positive value: about 1,
  or about 2 after don/haven/didn.
- "not" gives a sign that depends on the word just before it:
  * after a modal or "does/did" ("should not", "will not", "does not") it is negative (about -1);
  * after "is/are/was/were/do/may/might" it is weakly negative (about -0.5);
  * otherwise (after a pronoun contraction like "I'm not", a conjunction, "if", "but",
    punctuation) it is positive (about 1.1).
- Adverbs like "also", "never", "always", "only" right after an auxiliary are weakly negative.
- "be" after a modal ("might be", "must be") is slightly positive; "no" after is/are is mildly positive.
Everything else is 0.
"""
READS = ()

STRONG_NEG = {" should", " will", " would", " must", " can", " could", " shall", " does", " did"}
WEAK_NEG = {" is", " are", " was", " were", " do", " may", " might"}
AUX = STRONG_NEG | WEAK_NEG
NOT_WORDS = {" not", "not", " Not", "Not", " NOT"}
ADVERBS = {" never", " always", " also", " necessarily", " only"}
CONTRACTED = {"'t", "’t"}
MODALS = {" will", " should", " would", " might", " could", " may", " must", " can"}
DON_LIKE = {" don", " haven", " didn", " hadn", " Don"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in CONTRACTED:
        return None, 2.0 if prev in DON_LIKE else 1.0
    if tok in NOT_WORDS:
        if prev in STRONG_NEG:
            return None, -1.0
        if prev in WEAK_NEG:
            return None, -0.5
        return None, 1.1
    if tok in ADVERBS and prev in AUX:
        return None, -0.6
    if tok in (" be", "be") and prev in MODALS:
        return None, 0.15
    if tok == " no" and prev in WEAK_NEG:
        return None, 0.7
    return None, 0.0

