"""A small grammar-based estimate for recurring auxiliary constructions:
modal 'be', perfect 'been', contraction endings, and a few 'not' contexts.
The signs are only rough averages; the program does not infer the full sentence.
"""
READS = ()

MODALS = {"will", "must", "might", "could", "should", "may", "can",
          "would", "shall"}
PERFECT = {"have", "has", "had", "'ve", "’ve", "'s", "’s"}
NEGATIVE_CONTEXTS = {"does", "did", "is", "are", "could", "would"}
DISCOURSE_CONTEXTS = {"but", "were", "still", "i'm", "had"}


def previous_word(prefix):
    pos = len(prefix.token_ids) - 1
    doc = prefix.document_ids[pos]
    start = pos
    while start and prefix.document_ids[start - 1] == doc:
        start -= 1
    words = "".join(prefix.token_strings[max(start, pos - 4):pos]).lower().split()
    return words[-1].strip(".,;:!?()\"'`’") if words else ""


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    previous = previous_word(prefix)
    if token == "be" and previous in MODALS:
        return None, 0.45
    if token == "been" and previous in PERFECT:
        return None, 0.45
    if token in {"'t", "n't"}:
        return None, 0.30
    if token == "not":
        if previous in NEGATIVE_CONTEXTS:
            return None, -0.45
        if previous in DISCOURSE_CONTEXTS:
            return None, 0.45
    return None, 0.0

programs.sol:
"""A negative lexical response to distance and remoteness.

Distance/far words fire most strongly; direction, range, angles, proximity
and length units are weaker. The vocabulary includes several languages.
Short phrases ('how far', 'long distance') adjust the strength, and some
response continues onto a following preposition. This uses word spellings
and token pieces, not a judgment of the sentence's meaning. Other tokens
predict zero; the previous-word state resets at document boundaries.
"""
READS = ()

# Related spatial words, grouped by approximate response strength.
WORD_GROUPS = (
    (-3.65, 'remote distant'),
    (-3.2, 'farther'),
    (-2.8, 'remotely distancing далек distancia'),
    (-2.2, 'afar далеко'),
    (-1.5, 'direction nearer kilometres дальн'),
    (-1.3, 'dist xrange closer rural loin'),
    (-1.15, 'range away miles kilometers directions proximity'),
    (-1.0, 'nearest mileage mile angle weit entfer'),
    (-0.85, 'further closest spatial vicinity дальше'),
    (-0.7, 'ranges ranging ranged radians longitude'),
    (-0.6, 'angles yards geographic geographical'),
    (-0.45, 'apart territory suburbs terrain angular countryside spaced weiter'),
    # Chinese/Japanese/Korean distance, remoteness and direction vocabulary.
    (-6.5, '远 遠'),
    (-4.7, '远程 远方 远远 远处'),
    (-3.4, '距离 的距离 距離 深远'),
    (-2.8, '偏远 不远'),
    (-2.3, '近距离 远离 路程 千里'),
    (-1.5, '方向 的方向 范围 全程 距 遥 万里'),
    (-1.0, '近 公里 거리 范围内 角度 的角度'),
    (-0.8, '範 农村 地域 进一步'),
    (-0.5, '地区 地理 区域 离 離 隔 深'),
)
VALUES = {w: v for v, words in WORD_GROUPS for w in words.split()}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = '', 0.0
    if carry is not None and carry[0] == doc:
        previous, strength = carry[1:]
    token = prefix.token_strings[-1]
    bare = token.strip()
    if '\ufffd' in bare:
        # A byte-piece can complete a character from the spatial vocabulary.
        completed = prefix.text_prefixes[-1][-1:]
        if completed in VALUES:
            bare = completed
    word = bare.lstrip('._/(-').lower()
    value = VALUES.get(word, 0.0)

    if word in {'distance', 'distances'}:
        value = -4.1 if token.startswith(' ') else -3.5
        if bare.startswith('-') or previous in {'long', 'vast'}:
            value = -6.3
        elif previous == 'short':
            value = -5.4
    elif word == 'far':
        value = -3.9 if token.startswith(' ') else -2.5
        if previous == 'how':
            value = -5.3 if bare[:1].isupper() else -6.0
        elif bare[:1].isupper():
            value = -2.65
        elif previous in {'so', 'thus'}:
            value = -3.0
        elif previous == 'as':
            value = -4.45
    elif word == 'away':
        if previous in {'far', 'farther'}:
            value = -2.2
        elif previous == 'further':
            value = -1.5
        elif previous == 'right':
            value = -0.7
    elif word == 'further' and bare[:1].isupper():
        value = -0.43
    elif word == 'thest' and previous in {'far', 'fur'}:
        value = -2.9 if previous == 'far' else -2.5
    elif word in {'ance', 'ances'} and previous == 'dist':
        value = -2.7
    elif word in {'istance', 'istant'} and previous == 'd':
        value = -2.5

    # A smaller continuation onto the next grammatical word.
    if word == 'as' and previous == 'far':
        value = 0.6 * strength
    elif word == 'of' and previous in {
        'distance', 'distances', 'direction', 'directions', 'angle', 'angles'
    }:
        value = 0.5 * strength
    elif word == 'of' and previous in {'range', 'ranges', 'miles', 'mile'}:
        value = 0.25 * strength
    elif word == 'from' and previous in {'far', 'distance', 'distances', 'away'}:
        value = (0.45 if previous == 'far' else 0.2) * strength
    elif word == 'to' and previous in {'distance', 'distances'}:
        value = 0.1 * strength
    return (doc, word, value), float(value)

