"""A token-shape detector for backslash-escaped quotation marks.

An escaped double quote is strongest by itself or after a space, weaker
when joined to closing punctuation. Escaped single quotes and a few other
escaped punctuation marks produce a smaller response. Ordinary tokens
receive a near-zero prediction; no string-literal parsing is attempted.
"""
READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    before, escape, after = text.partition('\\"')
    if escape:
        if after.startswith(','):
            value = 0.68 if '\\' in after else 0.90
        elif after.startswith(':'):
            value = 1.04
        elif after.startswith('\\'):
            value = 1.00
        elif after.startswith((')', ']', '>')):
            value = 0.83
        elif after.startswith('"'):
            value = 0.95
        elif after:
            value = 1.40
        elif before.isspace():
            value = 2.13
        elif before.endswith('('):
            value = 1.75
        elif before.endswith(('.', '}')):
            value = 1.44
        elif before.endswith('{'):
            value = 1.63
        else:
            value = 1.80
        # Additional unescaped quotes or backslashes change the token shape.
        if '"' in before:
            value *= 0.50
        elif '\\' in before:
            value *= 0.22
        if '"' in after and not after.startswith('"'):
            value *= 0.40
        elif after.startswith('",'):
            value *= 0.55
        return None, value

    if "\\'" in text:
        return None, 0.33 if "'" in text.split('\\')[0] else 0.95
    if any(mark in text for mark in ('\\<', '\\/', '\\$', '\\%', '\\|')):
        return None, 0.19
    if '\\_' in text:
        return None, 0.13
    return None, 0.0

