"""A coarse approximation of a weak lexical and formatting component.

Longer tokens have a small negative baseline. Russian adjectival fragments and
tokens spelled like some English suffixes have larger signed responses.
Short accented Latin fragments tend positive; hiragana and two-character CJK
tokens negative.
Chat headers, message endings and tool tags have separate signed responses.
Document starts and distances from them also change the baseline.
These rules capture only a small fraction of the word-specific variation;
they do not identify a general semantic detector.
"""

import unicodedata

READS = ()

SUFFIXES = {
    'ological': -0.088, 'ically': -0.088,
    'ness': 0.077, 'al': 0.026, 'ous': -0.039,
}
INITIAL_PUNCTUATION = {
    '#': 0.110, ')': 0.073, ',': 0.082,
    '-': 0.051, '.': -0.015, ':': 0.042,
}


# Baseline and inverse-square-root position correction for chat-format tokens.
MARKUP = {
    '<|im_start|>': (-0.007365, 0.065273),
    '<|endoftext|>': (0.015821, -0.054479),
    '<think>': (-0.024164, 0.115578),
    '</think>': (-0.001779, 0.054370),
    '<tool_response>': (-0.011301, 0.066323),
    '<tool_call>': (-0.066580, 0.111715),
}
TOOL_CLOSERS = {'</tool_response>', '</tool_call>'}


def format_response(s, previous, position):
    if position == 0:
        return -0.000639 if s == '<|im_start|>' else None
    distance = (position + 1) ** -0.5
    if previous == '<|im_start|>' and s in {'user', 'assistant'}:
        if position == 1:
            return -0.034834 if s == 'user' else -0.014968
        return (0.074888 - 0.025313 * distance if s == 'user'
                else 0.024707 + 0.155539 * distance)
    if s in TOOL_CLOSERS:
        return -0.048632 + 0.091333 * distance
    if s == '<|im_end|>':
        return (-0.048165 + 0.151784 * distance if previous in TOOL_CLOSERS
                else 0.021177 + 0.026174 * distance)
    if s in MARKUP:
        base, correction = MARKUP[s]
        return base + correction * distance
    if s.isspace() and '\n' in s:
        if previous in {'assistant', '<think>', '<tool_response>'}:
            return 0.036378 + 0.030257 * distance
        if previous == '<|im_end|>':
            return -0.011472 + 0.009191 * distance
        if previous == '<tool_call>':
            return 0.016705
        if previous == '</think>':
            return 0.014916
    return None


def shape_response(s):
    word = s.strip().lower()
    if word.startswith(('ическ', 'альн')):
        return -0.160
    if s == s.strip() and word in SUFFIXES:
        return SUFFIXES[word]
    if s.isspace():
        return -0.003 if len(s) >= 3 else 0.001
    if any('\u3040' <= c <= '\u309f' for c in s):
        return -0.014
    if len(s) >= 5:
        if not s.isascii():
            return -0.027
        return -0.006 if word.isalpha() else 0.0
    if len(s) >= 3:
        return -0.003
    if any('\u3400' <= c <= '\u9fff' for c in s):
        return -0.012 if len(s) == 2 else -0.002
    if not s.isascii() and any('LATIN' in unicodedata.name(c, '') for c in s):
        return 0.014
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != document else carry[1] + 1
    s = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if position else None
    formatted = format_response(s, previous, position)
    if formatted is not None:
        value = formatted
    elif position == 0:
        word = s.strip().lower()
        if word in {'a', 'an', 'the'}:
            value = -0.032
        elif s in INITIAL_PUNCTUATION:
            value = INITIAL_PUNCTUATION[s]
        elif s.isspace():
            value = 0.022
        elif word == '0':
            value = 0.054
        elif word.isdigit():
            value = -0.006
        else:
            value = 0.012
    else:
        value = shape_response(s) + 0.012 / (position + 1) ** 0.8 - 0.0005
    return (document, position), float(value)

