        value = CHINESE[text]
        if text == '入' and previous == '輸':
            value = 3.4
    elif text == '입력':
        value = 4.1
    elif lower == 'get':
        value = 0.52 if text.startswith('.') else 0.25
    elif token == 'user':
        value = 0.24 if age <= 2 else 0.52
    elif token == 'arguments':
