    if _is_in(text, "؀", "ۿ"):
        return ARABIC
    if _is_in(text, "一", "鿿") or _is_in(text, "぀", "ヿ") or _is_in(text, "가", "힯"):
        return CJK
    if _is_in(text, "Ѐ", "ӿ"):
        return CYRILLIC
    if text.isascii() and text.isalpha():
        return LATIN_WORD if token.startswith(" ") else LATIN_PIECE
    if any(ch.isdigit() for ch in text):
        return DIGIT
    if not any(ch.isalnum() for ch in text):
        return PUNCT
    return OTHER


def step(carry, prefix, upstream):
    return carry, float(_script_class(prefix.token_strings[-1]))

programs.sol:
"""English HAVE constructions, especially 'have/has/had/having to'.

The adjacent HAVE + TO construction is strongly negative, and HAVE plus a
specified object ('the', a pronoun, a possessive) is moderately negative.
The response echoes on 'be'/'do' after HAVE TO.  NEED TO and BE TO give
smaller negative responses; modals strengthen NEED, HAVE, and HAVE TO.
Otherwise TO is mildly negative and other tokens are quiet. These are
coarse local rules, not a sentence parser: they use stripped, lowercased
token strings and remember only two tokens, resetting at each document.
"""
READS = ()
HAVE = {'have', 'has', 'had', 'having'}
NEED = {'need', 'needs', 'needed', 'needing'}
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
OBJECTS = {'me', 'you', 'him', 'her', 'us', 'them'}
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
FUTURE_CONDITIONAL = {'will', 'would', "'ll", '’ll', "'d", '’d'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    if carry is None or carry[0] != doc:
        previous = before = ''
    else:
        _, previous, before = carry
    value = 0.0
    if word in {'to', '_to', '-to', '.to'}:
        value = -0.32 if text == ' to' else -0.75
        if word == 'to':
            if previous in HAVE:
                value = -6.05 - (0.7 if before in FUTURE_CONDITIONAL else 0)
            elif previous in NEED or previous in BE:
                value = -1.05
    elif word == 'the':
        if previous == 'with':
            value = -0.55
        elif previous == 'without':
            value = -1.02
    elif word in {'need', 'have'}:
        if previous in FUTURE_CONDITIONAL:
            value = -1.3 if word == 'need' else -0.57
        elif previous in {'may', 'might'}:
            value = -0.75 if word == 'need' else -0.17
        elif previous in {'not', "'t", '’t'} and word == 'need':
            value = -0.5
        elif previous == 'to' and word == 'have':
            value = -0.4
    if previous in HAVE:
        if word == 'the':
            value = -2.95
        elif word == 'it':
            value = -1.7
        elif word in POSSESSIVES or word in OBJECTS:
            value = -1.2
        elif word in DEMONSTRATIVES or word == 'all':
            value = -0.85
        elif word in {'a', 'an'}:
            value = -0.24
        elif word in {'everything', 'everyone'}:
            value = -2.0
    elif previous == 'to' and before in HAVE:
        if word in {'be', 'do'}:
            value = -1.4
        elif word in {'go', 'get', 'find', 'tell'}:
            value = -0.8
        else:
            value = -0.15
    return (doc, word, previous), value

programs.haiku:
"""layers.0.mlp.down_proj:1576, written as a plain rule about words.

What it does. This component writes into the residual stream by its activation, which is
mostly negative on the word right after "have" (have / has / had / having), and most of all on
"to" there: "have to" (obligation), about -6. "have the" gives about -3, and "have it / them /
their / its / this / all" about -1. Every other "to" is mildly negative, about -0.3; after
words of need or obligation ("need to", "is to", "was to", "used to", "required to") it is
about -0.8; after ability and adjective words ("able to", "possible to", "easy to") it is
slightly positive, about +0.25; after object pronouns ("me to", "him to") about -0.5.
Everything else is predicted as 0.

Why. The component's variance is dominated by "to" tokens, and the largest activations come from
"have to". The word before the current token is all the rule needs, so the rule is causal.
It resets at document boundaries, as the model does.

What it leaves out. About 40% of the variance is not captured. The rest of it is diffuse,
small (std 0.06) and token-specific, with no clean concept behind it, so I left it at 0.
"""
READS = ()
HAVE = {" have", " has", " had", " having"}
NEED = {" need", " needs", " needed", " required", " supposed", " is", " was", " seems", " seem",
        " used", " found", " considered", " what", " but", " or", " and", " as"}
ABILITY = {" able", " unable", " possible", " easy", " decided", " opportunity", " applied",
           " close", " similar", " return", " access", " lead", " attempt", " back"}
OBJECT = {" me", " him", " you", " us", " them"}
DET = {" the", " it", " them", " their", " its", " your", " his", " her", " our", " my", " this",
       " all", " both", " everything"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""  # a new document starts here: nothing before it
    if prev in HAVE:
        if tok in (" to", "To"):
            return None, -6.0
        if tok == " the":
            return None, -3.0
        if tok in DET:
            return None, -1.0
        return None, 0.0
    if tok in (" to", "To"):
        if prev in NEED:
            return None, -0.8
        if prev in ABILITY:
            return None, 0.25
        if prev in OBJECT:
            return None, -0.5
        return None, -0.3
    return None, 0.0

programs.luna:
"""Approximate the component with short-word patterns.

It predicts a small negative activation on 'to', stronger after forms of 'need',
'is', 'was', and 'used', and much stronger after forms of 'have'.  It also
predicts a negative activation on 'the' after 'have', and a smaller one on 'be'
or 'do' in 'have to be/do'.  Everything else is predicted as zero.
"""

READS = ()
HAVE_FORMS = {"have", "has", "had", "having"}
TO_AFTER = {
    "need": -1.05,
    "needs": -1.05,
    "is": -0.9,
    "was": -1.1,
    "used": -0.65,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()
    previous = ""
    before_previous = ""
    same_previous = len(prefix.token_strings) > 1 and (
        prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    if same_previous:
        previous = prefix.token_strings[-2].strip().casefold()
    same_three = len(prefix.token_strings) > 2 and same_previous and (
        prefix.document_ids[-2] == prefix.document_ids[-3]
    )
    if same_three:
        before_previous = prefix.token_strings[-3].strip().casefold()

    if token == "to":
        if previous in HAVE_FORMS:
            return None, -6.0
        return None, TO_AFTER.get(previous, -0.45)

    if token == "the" and previous in HAVE_FORMS:
        return None, -3.0

    if previous == "to" and before_previous in HAVE_FORMS:
        if token == "be":
            return None, -1.4
        if token == "do":
            return None, -1.3
    return None, 0.0

programs.sol:
"""Spelling continuations after m, including its Greek/Cyrillic/Arabic forms.

Short continuations beginning a/e/i, l/d, or most other consonants give a
positive response; o/u give a negative response. Following n, l, or s
modifies the vowel response, and completing 'math' gives an extra positive
response. Long tokens weaken the effect, and capital M strengthens it.
An m inside the preceding token gives a much weaker version of the response.
This is a local spelling rule, not a detector of mathematical meaning.
"""
import math
import unicodedata
from functools import lru_cache

READS = ()
M = 'mмμم'
A = 'aаαا'
EI = 'eеэεiиіιı'
O = 'oоοωø'
U = 'uуυو'
LD = 'lлλdдδدل'
OTHER_LETTERS = 'bcfghjkqrstvwxyzбβبسсσتтτرрρηычцкгхф'


@lru_cache(maxsize=16384)
def spelling(token):
    return ''.join(
        c for c in unicodedata.normalize('NFD', token.casefold())
        if unicodedata.category(c) != 'Mn'
    )


@lru_cache(maxsize=16384)
def response(text):
    if not text:
        return 0.0
    first, length = text[0], len(text)
    groups = (
        (A, 1.11),
        (EI, 0.62),
        (O, -0.76),
        (U, -0.47),
        (LD, 1.01),
        (OTHER_LETTERS, 0.30),
    )
    value = next((v for letters, v in groups if first in letters), 0.0)
    peak_length = 1 if first in O + U + LD else 2
    value *= math.exp(-0.2 * max(0, length - peak_length))
    if length == 1 and first in A + EI:
        value *= 0.5

    adjustment = 0.0
    if length > 1:
        second = text[1]
        if first in A + EI:
            if second in 'nнνن':
                adjustment -= 0.43
            elif second in 'lлλل':
                adjustment += 0.25
        elif first in O + U:
            if second in 'lлλل':
                adjustment += 0.45
            elif second in 'sсσس':
                adjustment -= 0.66
    if text in ('ath', 'aths'):
        adjustment += 0.87
    return value + adjustment * math.exp(-0.2 * max(0, length - 2))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    text = spelling(token)
    strength = 0.0
    if text and text[-1] in M:
        strength = math.exp(-0.25 * max(0, len(text.strip()) - 3))
        if token[-1:].isupper():
            strength *= 1.2
    elif text.endswith(('me', 'ме', 'με')):
        strength = 0.30
    elif any(c in text for c in M):
        strength = 0.08

    value = 0.0
    if carry is not None and carry[0] == document:
        value = carry[1] * response(text)
    return (document, strength), float(value)

