programs.sol:
"""Recognize spaces in padding and tokens at uncontextualized starts.

A lone space after a space-ending token has a positive response, calibrated by
padding width and distance from the document start. At row/document starts,
spaces respond much more strongly; digits and punctuation also exceed words.
Coarse punctuation-specific gains approximate this initial response. An initial
run of identical tokens keeps it. Other interior tokens are nearly zero.
"""
READS = ()


def initial_response(token):
    if token == ' ':
        return 5.82
    if token and set(token) == {' '}:
        if len(token) == 2:
            return 4.12
        return max(1.0, 3.9 - 0.15 * len(token))
    if token.isspace():
        if '\n' in token:
            return 0.68 if token == '\n' else 0.35
        if '\t' in token:
            return 1.73 / len(token) ** 0.5
        return 1.54 if token == '\r' else 0.68
    if token.isdigit():
        return 0.69
    if token.startswith('<|'):
        return 0.18
    if token and len(set(token)) == 1:
        mark = token[0]
        if mark == '·':
            return 0.74
        if mark in '*_>':
            return 3.9
        if mark in '-/\\|"$%':
            return 2.6
        if mark in "#'`~":
            return 2.1
        if mark in '(+<@^[':
            return 1.4
        if mark in '.,)':
            return 0.85 if len(token) == 1 else 2.5
        if mark in '?:;=]{}':
            return 0.6
    if token and all(not c.isalnum() and not c.isspace() for c in token):
        return 0.35
    return 0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, position, initial_run = ('', 0, True) if first else carry[1:]
    if not first:
        position += 1
        initial_run = initial_run and token == previous
    value = 0.003
    if initial_run:
        value = initial_response(token)
    elif token == ' ' and previous.endswith(' '):
        width = len(previous)
        if position == 1 and previous.isspace():
            value = 0.92 * initial_response(previous)
        else:
            if previous == ' ':
                base, boost = 0.83, 2.66
            elif width == 2:
                base, boost = 0.66, 1.24
            elif width == 3:
                base, boost = 0.70, 1.47
            elif width < 8:
                base, boost = 0.58, 2.12
            else:
                base, boost = 0.52, 1.04
            value = base + boost / (position + 1) ** 0.5
    return (doc, token, position, initial_run), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1580 -- a "bare start" and "indent space" detector.

What it does, in plain terms:

1. Start of a document (or of a packed row). With no earlier text to look at, the
   component's response is set by the token alone, and it is strongest for symbols
   and whitespace, weak for words:
     - a lone space " " is the strongest response of all;
     - indentation runs ("   ", "\\t") and code-ish symbols ("#", "##", "-", "(") are big;
     - other punctuation, digits and newlines are moderate;
     - words (letters) are near zero.

2. Inside a text, a lone space " " that follows another whitespace token (i.e. a
   space inside an indentation run, typically the space just before a line number
   or the first character of code in an indented block) gives a moderate response.

3. A run of middle dots "·" (dotted leaders) gives a moderate response.

Everything else is treated as zero: the component is small and diffuse on ordinary
words and punctuation mid-text.

The values are rough averages measured on training text; they are not fitted to eval.
"""

READS = ()

CODE_SYMBOLS = {"#", "##", "-", "(", "--", "###"}


def _is_blank(s):
    """A run of spaces and/or tabs only, e.g. "  " or "\\t"."""
    return s != "" and all(c in " \t" for c in s)


def _is_word(s):
    """Letters only, optionally with a leading space: "The", " the"."""
    s = s.strip()
    return s != "" and s.isalpha()


def _is_symbol(s):
    """Non-empty, not a word, not blank: digits, punctuation, newlines."""
    return s.strip() != "" and not s.strip().isalpha()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]

    if start:
        if tok == " ":
            return carry, 5.8
        if _is_blank(tok):
            return carry, 2.5
        if tok.strip() in CODE_SYMBOLS:
            return carry, 2.0
        if _is_symbol(tok):
            return carry, 0.8
        if _is_word(tok):
            return carry, 0.15
        return carry, 0.0

    if tok == " " and _is_blank(prefix.token_strings[-2]):
        return carry, 0.83
    if tok != "" and set(tok) == {"·"}:
        return carry, 0.75
    return carry, 0.0

