"""A lexical ability signal with a broader Chinese grammatical-word response.

'Can' and its translations are positive, especially Chinese 可以. Chinese
auxiliaries, connectives, personal pronouns and time words also respond. Merged
Chinese compounds combine known markers or reuse a marker's strength with
a length discount. Pronoun + 'can' compounds have their own rough strengths.
English 'can' is strongest after 'we'; 'how' in the last four tokens reduces it.
Unmatched tokens, including most byte fragments, receive zero.
"""

READS = ()

# Strengths for recognizable grammatical word classes, not token IDs.
CHINESE_CLASSES = (
    (5.4, '可以'),                         # ability / permission
    (2.6, '不能 应该 應該 应当 應當'),      # prohibition / obligation
    (2.0, '能够 能夠'),                    # be able
    (2.0, '没有 沒有'),                    # absence
    (2.0, '自己 自己的'),                  # reflexivity
    (1.5, '需要 无法 無法'),               # need / inability
    (1.5, '如果 现在 現在'),               # if / now
    (3.0, '但是 而且'),                    # but / moreover
    (3.0, '的时候 的時候'),                # when
    (2.5, '或者 并且 並且 可是'),           # or / and / but
    (2.75, '已经 已經'),                   # already
    (2.1, '我们 我們'),                    # we
    (2.1, '时候 時候 以后 以後'),           # time / afterwards
    (1.1, '我 你 他 她 它 他们 他們 她们 她們 它们 它們 大家'),
    (1.2, '在 要 一个 一個 这个 這個 那个 那個 因为 因為 '
     '很多 更加 不要 必须 必須 不可'),
    (1.3, '且 咱们 咱們 之后 之後 这样 這樣 这样的 這樣的 这么 這麼'),
    (1.0, '我的 你的 他的 她的 它的 我们的 我們的 正在'),
    (1.5, '就是 所以 你们 你們 以前 后来 後來 仍然 是在'),
    (.8, '可 会 會 能 就 已 以 可能 还是 還是 一些 之前 然后 '
     '然後 虽然 雖然 同时 同時 不过 不過 以及 应 應 只能 该 該 '
     '如何 是否 想要 希望 喜欢 喜歡 通常 当然 當然 非常 只有 '
     '那么 那麼 以上 不是 一直 按照 其实 其實 为了 為了'),
    (.55, '很 个 個'),
    (.68, '但 即 因此'),
    (-.12, '的 了 和 与 與'),
    (.68, '是 都是 也是 只是'),
)
CHINESE = {word: value for value, words in CHINESE_CLASSES
           for word in words.split()}
MARKERS = sorted((word for word in CHINESE if len(word) > 1),
                 key=lambda word: (-CHINESE[word], -len(word)))
SEGMENTS = sorted(CHINESE, key=len, reverse=True)
ABILITY_CLASSES = (
    (1.6, 'можно puedes สามารถ'),
    (2.0, 'нельзя يمكن'),
    (.55, 'может могут kann können peut peuvent'),
    (.7, 'нужно'),
    (.9, 'dapat bisa può できる 出来る'),
    (1.2, 'podemos できます ことができます することができます'),
)
FOREIGN = {word: value for value, words in ABILITY_CLASSES
           for word in words.split()}
ENGLISH_MODALS = {'cannot': .85, 'should': -.17,
                  'shall': -.23, 'could': -.13, 'would': -.08}


def chinese_value(word):
    if word in CHINESE:
        return CHINESE[word]
    if '可以' in word:
        # Polite 'you can' versus first-person 'I/we can', then length.
        if '您' in word:
            return 2.9
        if word.startswith('我'):
            return 4.75
        return 4.35 if len(word) == 3 else 3.5
    rest, values, widths = word, [], []
    # Greedily split a merged token into known grammatical words.
    for marker in SEGMENTS:
        if marker in rest:
            rest = rest.replace(marker, '', 1)
            if CHINESE[marker] > 0:
                values.append(CHINESE[marker])
                widths.append(len(marker))
    if values and not rest:
        if word.startswith(('如果', '应该', '應該')):
            return max(values) / (1 + .2 * (len(word) - 2))
        return sum(values) / (1 + .4 * (len(word) - max(widths)))
    for marker in MARKERS:
        # If content remains, approximate just the strongest embedded marker.
        if marker in word:
            return CHINESE[marker] / (1 + .3 * (len(word) - len(marker)))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ()
    else:
        _, previous, recent = carry
    raw = prefix.token_strings[-1]
    word = raw.strip()
    low = word.lower()
    if word in FOREIGN or low in FOREIGN:
        value = FOREIGN.get(word, FOREIGN.get(low, 0.0))
    elif any('\u4e00' <= c <= '\u9fff' for c in word):
        value = chinese_value(word.strip('，。！？：；、（）“”.,!?:;()"\''))
    elif low == 'can':
        value = .24
        if previous.lower() == 'we':
            value = .6
        elif previous == 'I':
            value = .42
        elif previous.lower() == 'you':
            value = .32
        elif previous.lower() in ('which', 'one'):
            value = 0.0
        if 'how' in recent:
            value -= .45
        if word == 'Can':
            value += .1
    else:
        value = ENGLISH_MODALS.get(low, 0.0)
        if low == 'able':
            value = .21 if raw[:1].isspace() else -.07
    return (doc, word, (recent + (low,))[-4:]), float(value)

