CAN_ZH = ("可以", "能够", "不能", "无法", "只能")
# Necessity and possibility in Chinese: weaker.
NEED_ZH = ("需要", "应该", "必须", "可能", "要", "能")
# English and other-language "can" / "may" / "able to".
CAN_OTHER = {"can", "cannot", "можно", "нельзя", "できる", "ことができる", "สามารถ", "può", "peut"}
