        elif token.startswith('\t') and token[1:].strip(' ') == '':
            spaces = len(token) - 1
            value = 1.65 if spaces <= 5 else 1.08 if spaces <= 12 else 0.8
        elif '\n' in token:
            value = 0.6 if token == '\t\n' else 0.32
