def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    value = 0.0
    if word == 'peak':
        if raw.startswith(' '):
            value = -3.69 if token.istitle() else -3.42
        elif token.istitle():
            value = -3.11
        else:
            value = -1.15 if previous.lower().endswith('s') else -2.55
    elif word == 'peaks':
        value = -2.58 if token.istitle() else -2.94
    elif word == 'peaked':
        value = -2.06
    elif word == 'speaker':
        if token.istitle():
            value = -0.86
        elif not raw.startswith(' '):
            value = -0.40
        else:
            value = -0.775 if position == 0 else -1.11 - 0.42 / sqrt(position)
    elif word in SPEECH:
        value = SPEECH[word]
        if word == 'speaking' and token.istitle():
            value = -0.77
    elif word == 'peaker':  # End of a split word such as loudspeaker.
        value = -0.83
    elif word == 'peek':
        value = -1.12 if raw.startswith(' ') else -0.87
