"""Negative pulses at conditional and subordinate-clause introducers.

Prose 'if' is strongest. Indentation, comments, identifiers, 'else if',
and question verbs weaken it. Other clause words, familiar phrase endings
('long as', 'as soon'), and several translations have smaller pulses.
The numerical strengths summarize training measurements, not a parser.
Keep the last token and 160 characters of context, resetting at document
boundaries; predict zero for unrelated tokens. This omits the component's
weaker, token-specific background activity.
"""
READS = ()

# Lowercase and capitalized clause introducers (not arbitrary token IDs).
CLAUSES = {
    'when': (-1.05, -1.4), 'where': (-0.9, -0.95),
    'since': (-0.55, -0.9), 'until': (-0.74, -1.0),
    'unless': (-1.85, -1.5), 'while': (-0.05, -0.7),
    'once': (-0.35, -0.62), 'although': (-0.92, -1.1),
    'though': (-1.0, -1.0), 'whenever': (-0.55, -1.0),
    'wherever': (-0.64, -0.64), 'wherein': (-0.8, -0.8),
    'whereby': (-0.6, -0.6), 'whereas': (-0.4, -0.4),
    'because': (-0.15, -0.26), 'suppose': (-0.43, -0.55),
    'assuming': (-0.18, -0.45), 'iff': (-1.3, -1.3),
}
TRANSLATIONS = {
    'wenn': -1.35, 'если': -1.45, 'когда': -0.7,
    'quando': -0.8, 'cuando': -0.55, 'où': -0.6,
    '若': -1.35, '若是': -1.0, '当': -0.47, '當': -0.35,
    '一旦': -0.8,
}
QUESTION_VERBS = {'see', 'know', 'ask', 'wonder', 'determine', 'sure'}
CONNECTIVES = {'and', 'or', 'even', 'only', 'so'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        previous, recent = carry[1:]
    token = prefix.token_strings[-1]
    surface = token.strip()
    word = surface.lstrip('“"(->._—').casefold()
    prev = previous.strip().casefold()
    capital = surface[:1].isupper()
    boundary = previous.rstrip().endswith((',', '.', '?', '!', ';'))
    code = (';' in recent or ('{' in recent and '}' in recent)
            or ('_' in recent and '=' in recent)
            or '\\t' in recent or '\\n' in recent)
    value = 0.0
    if word == 'if':
        if surface.startswith(('_', '.')):
            value = -0.9                    # identifier or attribute
        elif surface.startswith('('):
            value = -1.1
        elif word != surface.casefold():
            value = -2.2 if 'If' in token else -1.8
        elif surface.isupper():
            value = -1.65 if token.startswith(' ') else -1.3
        elif capital:
            if not previous:
                value = -3.65 if token.startswith(' ') else -4.35
            elif prev in {'#', '//', 'end'}:
                value = -1.3
            elif prev in {'-', '*'}:
                value = -2.1
            else:
                value = -2.25 if code else -2.95
        elif '\t' in token:
            value = -0.2
        elif previous.isspace() and '\n' not in previous:
            deep_indent = '\t' not in previous and len(previous) >= 7
            value = 0.1 if deep_indent else -0.2
        elif prev in {'else', 'elif', 'check', 'checking', 'checks'}:
            value = -0.2
        elif prev in QUESTION_VERBS:
            value = -1.3
        elif not token.startswith(' '):
            value = -1.45
        elif prev == 'as':
            value = -3.9
        elif prev in {'but', 'that'}:
            value = -3.25
        elif boundary or prev in CONNECTIVES:
            value = -2.65
        else:
            value = -1.15 if code else -2.0
    elif word == 'as' and prev in {'long', 'soon', 'just'}:
        value = -1.7 if prev == 'long' else -0.8
    elif word == 'soon' and prev == 'as':
        value = -0.85
    elif word in CLAUSES:
        value = CLAUSES[word][capital]
        if word in {'when', 'since', 'while'} and boundary and not capital:
            value = {'when': -1.4, 'since': -0.75, 'while': -0.35}[word]
        if word == 'when' and code and not capital and not boundary:
            value = -0.75
        if word == 'while' and not capital and previous.isspace():
            value = 0.25
        if word == 'where' and surface.isupper():
            value = -0.45
        if word == 'though':
            if prev == 'as':
                value = -3.0
            elif prev == 'even':
                value = -1.5
        if word == 'iff' and not token.startswith(' '):
            value = -0.1
    elif '如果' in word:
        value = -1.7
    else:
        value = TRANSLATIONS.get(word, 0.0)
    return (doc, token, (recent + token)[-160:]), value

