programs.haiku:
"""Layer-0 MLP neuron 1592 (down_proj): the second word of a compound identifier.

Source code builds long names from several words: `packageNames`, `itemsJson`,
`file_path`, `enemy_count`. This neuron fires on the token that begins the second word of
such a name when it is glued to the word before it with no space: a capital letter after a
lowercase or uppercase word (camelCase), or an underscore after a word (snake_case).
Its strength depends on the two words:

- a real word after a name-like stem (package|Names, path|Param, items|Json, CSS|Rules): strong;
- a single letter or acronym after a stem (fooA, fooDNA): weak;
- after the accessor verbs get or set, the name is a method, e.g. obj.get|Metadata: negative.

Everything else (ordinary words, spaces, punctuation) gives 0.
"""

READS = ()

ACCESSORS = {"get", "set"}


def _is_word(piece):
    """A real word such as Names or path, not a single letter or an acronym like DNA."""
    body = piece.strip("_")
    return len(body) >= 3 and (body.islower() or (body[0].isupper() and body[1:].islower()))


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    if not tok or tok[0].isspace() or not prev or not (prev[-1].isalnum() or prev[-1] == "_"):
        return carry, 0.0
    stem = prev.lstrip(".").strip()
    if tok[0].isupper():
        if stem in ACCESSORS:
            return carry, -0.6
        if stem[-1].isupper():
            return carry, 0.6 if _is_word(tok) else 0.0
        return carry, 1.1 if _is_word(tok) else 0.2
    if tok[0] == "_":
        return carry, 0.7 if _is_word(tok) else 0.2
    return carry, 0.0

