"""Mostly a typographic-dash response, with a few weaker secondary responses.

Single em dashes usually respond most strongly; en and double em dashes
respond less. Early, infrequent, space-prefixed em dashes receive a boost.
Single em dashes weaken after Cyrillic tokens and when fused with a word
or newline; spaced en dashes also weaken after Cyrillic tokens, and newline
fusion weakens any en dash. State resets at each document boundary.

Smaller positive responses cover comparison operators, minus signs,
opening guillemets, horizontal bars, and tokens with ASCII ellipses and
newlines. Tokens spelling security, secure, privacy, or password receive
negative responses, ignoring case and surrounding spaces, tabs, underscores,
periods, or hyphens. Other tokens return zero; smaller lexical variation is
not reproduced.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous_dashes, previous = 0, 0, ''
    else:
        _, position, previous_dashes, previous = carry
    text = prefix.token_strings[-1]
    early = math.exp(-position / 32)
    cyrillic = any('\u0400' <= c <= '\u052f' for c in previous)
    if '——' in text:
        value = 1.1
    elif '—' in text:
        value = (2.0 + 1.35 / math.sqrt(1 + previous_dashes)
                 + 0.7 * early + 0.48 * text.startswith(' ')
                 - 0.6 * cyrillic)
        if any(c.isalpha() for c in text) or '\n' in text:
            value *= 0.53
    elif '–' in text:
        value = 0.8 + 0.2 * early
        if text.startswith(' '):
            value += 0.07 + 0.55 * early - 0.23 * cyrillic
        value -= 0.15 * math.log1p(previous_dashes)
        if '\n' in text:
            value *= 0.45
    else:
        value = punctuation_or_security(text)
    previous_dashes += '—' in text
    return (doc, position + 1, previous_dashes, text), float(value)


def punctuation_or_security(text):
    """Smaller responses to other symbols, and a security/privacy word family."""
    symbol = text.strip()
    if symbol in ('===', '!=='):
        return 0.55 if text.startswith(' ') else 0.31
    if symbol == '==':
        return 0.11
    if symbol in ('−', '«'):
        return 0.28 if text.startswith(' ') else 0.14
    if symbol == '―':
        return 0.9
    if '...' in text and '\n' in text:
        return 0.4 if not text.startswith(' ') else 0.28
    word = text.strip(' \t_.-').lower()
    if word == 'security':
        return -0.95
    if word in ('secure', 'privacy'):
        return -0.5
    if word == 'password':
        return -0.32
    return 0.0

programs.luna:
"""Estimate the component as a response to dash punctuation.

At this early layer, its strongest recurring signal is an en dash or em dash.
Spaced em dashes tend to elicit a larger response than ranges or hyphens.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    dashes = [ch for ch in token if unicodedata.category(ch) == "Pd"]
    if not dashes:
        return None, 0.0

    if "—" in dashes:
        if len(dashes) > 1:
            value = 0.9
        elif token.startswith(" "):
            value = 3.5
        else:
            value = 2.7
    elif "–" in dashes:
        value = 0.95
    else:
        value = 0.3
    return None, float(value)

programs.sol:
"""A detector for dot-attached identifiers and document-end markers.

A period joined to a lowercase name gets a positive pulse, especially for
recognizable filename suffixes. Capitalized names, familiar domain endings,
and several common methods get smaller pulses. Prose abbreviations and
sentence-starting words are treated separately, not as code members.
The period and name must share a token. All other text is approximated by
zero, except for a positive end-of-text pulse. Only the previous token is
remembered, with memory reset at document boundaries.
"""
READS = ()

SOURCE_SUFFIXES = frozenset('py go java js ts rs cpp cs rb php sh'.split())
DATA_SUFFIXES = frozenset('yaml yml json xml csv ini cfg'.split())
TEXT_SUFFIXES = frozenset('md txt html htm css rst'.split())
FILE_SUFFIXES = frozenset('png jpg jpeg gif pdf svg dll exe jar'.split())
ACCESS_VERBS = frozenset('get set add put load find is'.split())
LIST_METHODS = frozenset('push append join'.split())
SENTENCE_STARTERS = frozenset('The This It We He She There And As'.split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    name = token[1:] if token.startswith('.') else ''
    value = 0.0
    if token == '<|endoftext|>':
        value = 0.77
    elif token in ('._', '.__'):
        value = 0.95
    elif name and name.isascii() and name.isalpha():
        if (name == 'e' and previous.strip() == 'i') or (
            name == 'g' and previous.strip() == 'e'
        ):
            value = -0.12
        elif name == 'm' and previous.strip() in ('a', 'p'):
            value = 0.32
        elif name == 'S' and previous.strip() == 'U':
            value = -0.20
        elif name in SENTENCE_STARTERS:
            value = 0.10
        elif name == 'py':
            value = 2.90
        elif name == 'go':
            value = 2.65
        elif name in SOURCE_SUFFIXES or name in DATA_SUFFIXES:
            value = 2.30
        elif name in TEXT_SUFFIXES or name in FILE_SUFFIXES:
            value = 1.98
        elif name in ('com', 'net', 'edu', 'io'):
            value = 1.15
        elif name == 'org':
            value = 0.80
        elif name in ACCESS_VERBS:
            value = 1.28
        elif name in LIST_METHODS or name == 'log':
            value = 0.95
        elif name in ('println', 'Println', 'Printf'):
            value = 0.43
        elif name in ('sub', 'sup'):
            value = 1.03
        elif name == 'out':
            value = 0.66
        elif len(name) == 1:
            value = 0.40 if name.isupper() else 1.38
        elif not name.islower():
            value = 1.04
        else:
            value = 1.65
    return (doc, token), value

"""Approximate a local spelling interaction centered on nasal-to-g/h clusters.

Strong training responses often involve short g/h fragments after n-ending
fragments. Select a small response table by the current Latin fragment and
previous ending; weaken it at word boundaries, after long fragments, and for
some mixed-case pairs. Include explicit non-Latin counterparts and short
n-ending apostrophe patterns. Most other tokens get a small ending-dependent
background value. NUL separators do not replace the remembered fragment.
This leaves much of the weaker, token-specific variation unmodeled.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()
# Columns: n, m, vowel, other consonant, delimiter, n followed by a vowel.
KINDS = ('n', 'm', 'vowel', 'consonant', 'other', 'near_n')
RESPONSE = {
    'g': (-2.3, -0.85, 0.24, -0.35, -0.13, -0.3),
    'G': (-2.0, -0.55, 0.28, -0.08, 0.06, -0.3),
    'h': (-1.4, -0.23, 0.16, 0.0, 0.02, -0.05),
    'H': (-0.85, -0.3, 0.06, 0.0, -0.02, 0.0),
    'g_short': (-1.35, -0.4, 0.22, -0.13, 0.01, -0.2),
    'g_long': (-0.8, -0.12, 0.09, -0.07, -0.02, -0.1),
    'h_short': (-0.6, -0.1, 0.09, 0.01, 0.03, -0.04),
    'h_long': (-0.2, -0.03, 0.03, 0.0, -0.01, -0.02),
}

@lru_cache(maxsize=8192)
def ending(s):
    if not s:
        return 'other'
    c = s[-1]
    if '가' <= c <= '힣':
        final = (ord(c) - 0xAC00) % 28
        if final == 4:
            return 'n'
        if final == 16:
            return 'm'
        return 'vowel' if final == 0 else 'consonant'
    plain = ''.join(c for c in ud.normalize('NFD', s[-3:].lower())
                    if ud.category(c) != 'Mn')
    c = plain[-1:]
    if c in ('n', 'н', 'ن', 'ン', 'ん'):
        return 'n'
    if c in ('m', 'м', 'م'):
        return 'm'
    if c in tuple('aeiouyаеёиоуыэюя'):
        if len(plain) > 1 and plain[-2] in 'nн':
            return 'near_n'
        return 'vowel'
    return 'consonant' if c.isalpha() else 'other'


def response(token, prev):
    kind = ending(prev)
    i = KINDS.index(kind)
    body = token.lstrip()
    value = (0.024, 0.013, -0.009, -0.002, -0.002, -0.009)[i]
    if not body:
        return value
    c, n = body[0], len(body)
    spaced = token[0].isspace()
    if c in 'gGhH':
        if spaced and n > 1:
            return -0.04 if kind == 'n' and c.lower() == 'g' else -0.01
        group = c if n == 1 else c.lower() + ('_short' if n <= 3 else '_long')
        value = RESPONSE[group][i]
        if prev[-1:].lower() in ('b', 'p'):
            value = RESPONSE[group][1] * (0.6 if prev[-1:].lower() == 'b' else 1)
        if kind == 'n':
            length = len(prev.strip())
            value *= 0.4 if length > 5 else 0.75 if length > 3 else 1.0
            if c.isupper() and not prev[-1:].isupper():
                if c == 'G':
                    value *= 0.55 if n <= 3 else 0.15
                else:
                    value *= 0.1 if 1 < n <= 3 else 0.3
        if spaced:
            value *= 0.2 if c.lower() == 'g' else 0.05
            if kind == 'n' and prev[-1:].isupper():
                value *= 2
        if c == 'G' and n == 1 and prev.endswith('H'):
            value = 0.65
        return value
    if spaced:
        return value
    if c in 'гГґҐ':
        value = (-1.55, -0.7, 0.23, -0.23, -0.07, -0.45)[i]
        return value * 0.5 if n > 1 and kind != 'near_n' else value
    if c in 'گغج':
        return -1.3 if kind == 'n' else 0.08
    if body == 'ня':  # Palatal n syllable.
        return -0.8 if kind == 'n' else 0.22
    if body == '가':  # Korean ga, also a subject particle.
        return -1.2 if kind == 'n' else 0.6 if kind == 'vowel' else 0.25
    if '가' <= c <= '힣' and (ord(c)-0xAC00)//588 in (0, 1, 18):
        return (-0.8 if kind == 'n' else 0.03) * (0.4 if n > 2 else 1)
    if c in 'ガギグゲゴがぎぐげご':
        return (-1.1 if n == 1 else -0.65) if kind == 'n' else 0.04
    if kind == 'n':
        if c in 'jJ':
            return -0.3 if n == 1 else -0.6 if n <= 3 else -0.1
        if c in 'ジじ':
            return -0.35
        if c.lower() in 'дدжdь':
            strength = {'д': -0.45, 'د': -0.45, 'ж': -0.7, 'd': -0.22, 'ь': -0.32}
            return strength[c.lower()] * (1 if n <= 3 else 0.3)
    if body in ("'", '’'):
        if kind == 'n' and len(prev.strip()) <= 3:
            return -0.18 if len(prev.strip()) == 1 else -0.6
        return -0.02
    return value - (0.005 if body.isalpha() else 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    if token == '\x00':
        return (doc, prev), 0.14 if ending(prev) == 'n' else 0.01
    return (doc, token), float(response(token, prev))

