"""A weak cue for the standalone letter g, which often has a negative response."""

READS = ()


def step(carry, prefix, upstream):
    if prefix.token_strings[-1].strip() == "g":
        return None, -0.15
    return None, -0.00183

programs.haiku:
"""Initials detector (layer 0, MLP down-projection feature 1598).

What it does: it fires on a single capital letter token that is most likely the initial of a
person's name, or an abbreviation, as in "J. Smith", "Robert F. Kennedy", "Hendriks, R. C.".
Its size depends on the token just before the letter:
  - after punctuation, a line break, or a space (as in lists and citations): high;
  - after a preposition or conjunction that often comes before a name ("by", "of", "and"): high;
  - after a clause word ("if", "when", "that") or a code/maths symbol: near zero.
It is also a little stronger for letters that are common surname initials (C, F, G, H, J, M,
P, S, W...) and weaker for rare ones (Q, X, Z, U, O, V...), and it is weak for Cyrillic
capitals. The English words "I" and "A" and all other tokens predict 0.
"""

READS = ()

# Prepositions and conjunctions that often come right before a name: "by J", "of M", "and K".
LINK_WORDS = {"by", "of", "with", "from", "in", "at", "between", "and", "or", "the", "to", "as", "von", "und"}
# Clause words that come before ordinary words or variables, not names: "if X", "when X".
CLAUSE_WORDS = {"if", "when", "but", "which", "where", "that", "for", "is", "so", "do", "can", "then"}
# Code and maths symbols.
SYMBOLS = set("{}$=+*!?/\\`#<>&%^~_@|")
# Latin capitals that are common as surname initials; the others are rarer.
COMMON_INITIALS = set("CFGHJKMPRSTW")


def step(carry, prefix, upstream):
    core = prefix.token_strings[-1].lstrip(" .-('\"[,")
    if len(core) != 1 or not core.isupper() or core in ("I", "A"):
        return carry, 0.0
    if not core.isascii():
        return carry, 0.05  # Cyrillic and other non-Latin capitals
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.03  # first token of a document
    word = prefix.token_strings[-2].strip()
    if word in LINK_WORDS:
        value = 0.25
    elif word in CLAUSE_WORDS:
        value = 0.03
    elif not word:
        value = 0.3  # space or newline before the letter
    elif not any(ch.isalnum() for ch in word):
        value = 0.05 if word in SYMBOLS else 0.3  # punctuation such as "." "," "("
    elif word.isdigit():
        value = 0.2
    else:
        value = 0.1
    if value > 0.05:
        value *= 1.3 if core in COMMON_INITIALS else 0.6
    return carry, value

programs.sol:
"""Lexical occupancy and spatial-layout response, not a full semantic parser.

The largest predictions belong to 占/佔 (occupy/account for) and forms of
'occupy'/'occupation', including split word endings.
Related overlap, housing, layout and shape words are weaker. The particle
'up' depends on the preceding verb: 'take up'
and 'make up' are positive, while 'grow up' and 'set up' are negative.
A pronoun can intervene between a verb and 'up'. Most other text is zero;
small unrelated token-specific effects are deliberately left unexplained.
"""
READS = ()

OCCUPATION_WORDS = {
    'occupation': 3.0, 'occupations': 2.3, 'occupational': 1.8,
    'occupied': 2.5, 'occupy': 2.5, 'occupies': 3.0,
    'occupying': 2.8, 'occupancy': 2.5, 'occupants': 1.2,
    'occupant': 1.0, 'occupier': 1.5, 'occupiers': 1.2,
    'occupationally': 0.7,
}
CHINESE_WORDS = {
    '占': 8.7, '佔': 6.8, '占据': 4.7, '占据了': 4.5,
    '占用': 4.1, '占比': 3.7, '占有': 3.4, '占地': 3.4,
    '占领': 3.0, '占有率': 1.9, '占地面积': 1.6, '约占': 5.4,
    '居': 1.2, '住': 0.8, '居住': 0.75, '居家': 1.0,
    '住房': 0.5, '住宅': 0.35, '宅': 0.65, '位居': 1.6,
    '布局': 1.1, '卡': 1.1, '耗': 1.3,
}
# These are verb families, not a list of arbitrary tokenizer ids.
PRONOUNS = {'it', 'them', 'him', 'her', 'me', 'us', 'you'}
UP_VERBS = (
    (1.44, {'take', 'takes', 'took', 'taken', 'taking'}),
    (1.1, {'make', 'makes', 'made', 'making'}),
    (0.9, {'go', 'goes', 'going', 'went', 'gone'}),
    (0.7, {'put', 'puts', 'putting', 'cut', 'cuts', 'cutting'}),
    (-0.7, {'grow', 'grows', 'grew', 'grown', 'growing'}),
    (-0.17, {'set', 'sets', 'setting', 'show', 'shows', 'showed',
             'showing', 'look', 'looks', 'looked', 'looking'}),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = '', ''
    if carry is not None and carry[0] == doc:
        previous, before = carry[1:]
    token = prefix.token_strings[-1]
    bare = token.strip()
    word = bare.lower()
    split = (previous in {'occup', 'ocup'}
             and token == bare and bare.isalpha())
    if split:
        word = previous + word
    value = 0.0
    if bare in CHINESE_WORDS:
        value = CHINESE_WORDS[bare]
    elif '占' in bare or '佔' in bare:
        value = max(1.5, 5.0 - 0.7 * len(bare))
    elif word in OCCUPATION_WORDS:
        value = OCCUPATION_WORDS[word]
        if split:
            value *= 0.5 if word == 'occupations' else 0.9
        elif not token.startswith(' ') and word in {'occupation', 'occupied'}:
            value -= 0.8
    elif word.startswith(('occup', 'ocup')):
        value = 0.5 if split else (2.6 if bare[0].isupper() else 1.7)
    elif word in {'зан', 'зани', 'занима', 'занят'}:
        value = 1.2
    elif token == ' up':
        value = 0.23
        for strength, verbs in UP_VERBS:
            if previous in verbs:
                value = strength
                break
            if previous in PRONOUNS and before in verbs:
                value = 0.7 * strength
                break
    elif word.startswith('overlap') or word == '_overlap':
        value = 0.85 if word == 'overlapping' else 1.2
    elif word.lstrip('._/(') in {'layout', 'layouts', 'grouplayout'}:
        value = 0.9 if word.endswith(('layouts', 'grouplayout')) else 0.6
    elif word.endswith('layoutinflater') and token.startswith('.'):
        value = 0.65
    elif word in {'urban', 'spatial', 'shape', '.shape', 'shapes'}:
        value = 0.7 if word == 'urban' else 0.35
    elif word in {'comprising', 'constit', 'constitute', 'constitutes'}:
        value = 0.45
    elif word in {'dominate', 'domination', 'dominates'}:
        value = 0.7
    elif word == 'of' and previous.startswith('occup'):
        value = 1.1
    return (doc, word, previous), float(value)
